1	# The Entire CLI (https://github.com/entireio/cli), the session-capture
2	# tooling. Upstream ships no flake, so the package wraps its pinned release
3	# tarballs: one per supported system, hash-locked against the release's own
4	# checksums.txt. A version bump is a deliberate edit here: the version
5	# string plus the four hashes, taken from the new release's checksums.
6	{ ... }:
7	{
8	  perSystem =
9	    { pkgs, lib, ... }:
10	    {
11	      packages.entire =
12	        let
13	          version = "0.10.2";
14	          sources = {
15	            "aarch64-darwin" = {
16	              target = "darwin_arm64";
17	              hash = "REDACTED";
18	            };
19	            "x86_64-darwin" = {
20	              target = "darwin_amd64";
21	              hash = "REDACTED";
22	            };
23	            "aarch64-linux" = {
24	              target = "linux_arm64";
25	              hash = "REDACTED";
26	            };
27	            "x86_64-linux" = {
28	              target = "linux_amd64";
29	              hash = "REDACTED/vy0ABwHh0RP4=";
30	            };
31	          };
32	          inherit (sources.${pkgs.stdenv.hostPlatform.system}) target hash;
33	        in
34	        pkgs.stdenvNoCC.mkDerivation {
35	          pname = "entire";
36	          inherit version;
37	
38	          src = pkgs.fetchurl {
39	            url = "https://github.com/entireio/cli/releases/download/v${version}/entire_${target}.tar.gz";
40	            inherit hash;
41	          };
42	
43	          # why: the tarball unpacks flat; a fixed source root keeps the
44	          # layout assumption explicit.
45	          unpackPhase = ''
46	            mkdir source
47	            tar -xzf "$src" -C source
48	          '';
49	          sourceRoot = "source";
50	
51	          installPhase = ''
52	            runHook preInstall
53	            install -Dm755 entire "$out/bin/entire"
54	            runHook postInstall
55	          '';
56	
57	          doInstallCheck = true;
58	          installCheckPhase = ''
59	            "$out/bin/entire" --help >/dev/null
60	          '';
61	
62	          meta = {
63	            description = "The Entire CLI: agent-session checkpoints alongside commits";
64	            homepage = "https://github.com/entireio/cli";
65	            license = lib.licenses.mit;
66	            mainProgram = "entire";
67	            platforms = lib.attrNames sources;
68	          };
69	        };
70	    };
71	}
