2	 * The narinfo document: parsing, serialising, and the reference graph.
3	 *
4	 * A narinfo is a flat list of `Key: value` lines describing one store path
5	 * (`docs/contracts.md` §The narinfo format). cachet cares about it for two reasons: the `URL`
6	 * field names the NAR that must already exist before the narinfo may be stored
7	 * (Invariant NEVER-DANGLE), and the `References` field is the graph the collector walks
8	 * (ADR 0001) — there is no other copy of it anywhere.
9	 *
10	 * Unknown fields are preserved verbatim. We are a cache, not an authority on the format. A
11	 * field we do not understand must survive a store-and-serve cycle untouched, or we corrupt
12	 * artifacts for a client that does understand it — and clients verify signatures over content we
13	 * would have altered.
14	 *
15	 * The parser is total: arbitrary bytes yield a typed failure, never a throw
16	 * (Invariant CLIENT-CANNOT-CRASH).
17	 *
18	 * @module
19	 */
20	
21	import { NARINFO_BYTES_MAX, NARINFO_LINES_MAX, NARINFO_REFERENCES_MAX } from '../constants.js';
22	import { fail, ok, type Result } from '../result.js';
23	import type { NarKey, StorePathHash } from '../types.js';
24	import { parseNarKey, parseStorePath, parseStorePathBasename } from './keys.js';
25	
26	/** The fields cachet reads, plus everything it does not. */
27	export interface Narinfo {
28	    /** The full `/nix/store/<hash>-<name>` path this document describes. */
29	    readonly storePath: string;
30	    /** The NAR's bucket key. The object the write path checks for. */
31	    readonly url: NarKey;
32	    /** How the NAR is compressed. Defaults to `bzip2` when absent, as Nix does. */
33	    readonly compression: string;
34	    /** Hash of the compressed NAR. Absent for some uncompressed layouts. */
35	    readonly fileHash: string | undefined;
36	    readonly fileSizeBytes: number | undefined;
37	    /** Hash of the uncompressed NAR — what `nix store verify` checks. */
38	    readonly narHash: string;
39	    readonly narSizeBytes: number;
40	    /** `<hash>-<name>` basenames. The collector's edge list. */
41	    readonly references: readonly string[];
42	    /** May appear more than once; clients verify these against their trusted keys. */
43	    readonly signatures: readonly string[];
44	    /** Every line whose key we do not recognise, verbatim and in order. */
45	    readonly extraLines: readonly string[];
46	}
47	
48	/** why: Nix's own default when the field is absent (`docs/contracts.md`). */
49	const DEFAULT_COMPRESSION = 'bzip2';
50	
51	const SINGLE_VALUE_FIELDS = [
52	    'StorePath',
53	    'URL',
54	    'Compression',
55	    'FileHash',
56	    'FileSize',
57	    'NarHash',
58	    'NarSize',
59	    'References',
60	] as const;
61	
62	/** Fields collected during a parse, before validation. */
63	interface FieldBag {
64	    readonly single: Map<string, string>;
65	    readonly signatures: string[];
66	    readonly extraLines: string[];
67	}
68	
69	/** A non-negative integer, strictly — no signs, no whitespace, no exponents. */
70	function parseByteCount(text: string, field: string): Result<number> {
71	    if (!/^\d+$/.test(text)) {
72	        return fail('malformed_narinfo', `${field} is a non-negative integer`);
73	    }
74	    const value = Number(text);
75	    if (!Number.isSafeInteger(value)) {
76	        return fail('malformed_narinfo', `${field} is too large to represent exactly`);
77	    }
78	    return ok(value);
79	}
80	
81	/** A hash field: opaque to us, but it must at least be one non-empty token. */
82	function checkHash(text: string, field: string): Result<string> {
83	    if (text.length === 0 || /\s/.test(text)) {
84	        return fail('malformed_narinfo', `${field} is a single non-empty token`);
85	    }
86	    return ok(text);
87	}
