262	 *
263	 * Fields are emitted in a canonical order and unknown lines follow verbatim, so
264	 * `parseNarinfo(serializeNarinfo(x))` reproduces `x`. Serialising does not reproduce the original
265	 * document byte for byte, because field order in the input is not meaningful and is not preserved.
266	 * No information is lost, so a client's signature over the content stays valid.
267	 */
268	export function serializeNarinfo(narinfo: Narinfo): string {
269	    const lines = [
270	        `StorePath: ${narinfo.storePath}`,
271	        `URL: ${narinfo.url}`,
272	        `Compression: ${narinfo.compression}`,
273	    ];
274	
275	    if (narinfo.fileHash !== undefined) {
276	        lines.push(`FileHash: ${narinfo.fileHash}`);
277	    }
278	    if (narinfo.fileSizeBytes !== undefined) {
279	        lines.push(`FileSize: ${String(narinfo.fileSizeBytes)}`);
280	    }
281	
282	    lines.push(`NarHash: ${narinfo.narHash}`, `NarSize: ${String(narinfo.narSizeBytes)}`);
283	    lines.push(`References: ${narinfo.references.join(' ')}`);
284	
285	    for (const signature of narinfo.signatures) {
286	        lines.push(`Sig: ${signature}`);
287	    }
