//! The lease document: one per project, under `roots/{project}`.
//!
//! A lease is cachet's only garbage-collection state. There is no database:
//! the collector reads these documents, walks the closures of the paths
//! they name, and treats everything unmarked and older than the grace
//! window as collectable.
//!
//! Two consequences follow. Last write wins: a lease asserts what a project
//! needs now rather than a history of what it once needed, so a renewal
//! replaces the previous document wholesale and a path that drops out of
//! the closure stops being protected — which is the only reason the cache
//! does not grow forever. And provenance comes from the verified OIDC
//! token, never from the request body: a commit SHA a client could choose
//! for itself would be worthless as an audit trail.

use crate::constants::{LEASE_RETENTION_MS, UNKNOWN_CLAIM};
use crate::error::{ClientError, Result};
use crate::types::{ProjectName, UnixMillis};

/// What `roots/{project}` holds.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct LeaseDocument {
    /// The project this lease covers; also the key suffix.
    pub project: String,
    /// When this lease was last renewed, in epoch milliseconds. The
    /// collector compares it against lease retention.
    #[serde(rename = "renewedAtMs")]
    pub renewed_at_ms: u64,
    /// `owner/repo`, from the verified token.
    pub repository: String,
    /// The ref that renewed it: always the configured default branch by the
    /// time it is written.
    #[serde(rename = "ref")]
    pub ref_: String,
    /// The workflow run, from the verified token.
    #[serde(rename = "runId")]
    pub run_id: String,
    /// The commit that built these paths, from the verified token.
    #[serde(rename = "commitSha")]
    pub commit_sha: String,
    /// The flake installables the job built, for the record.
    pub installables: Vec<String>,
    /// The store paths whose closures must stay alive.
    #[serde(rename = "storePaths")]
    pub store_paths: Vec<String>,
}

impl LeaseDocument {
    /// Serialize the lease. Golden-locked: the worker writes it, the
    /// collector reads it, and offline tooling depends on the shape, so the
    /// keys emit in a fixed order with two-space indent and a trailing
    /// newline and a diff between two runs stays legible.
    pub fn serialize(&self) -> String {
        let mut body =
            serde_json::to_string_pretty(self).expect("the document fields are string-like");
        body.push('\n');
        body
    }

    /// Parse a lease, defensive about everything except the two fields the
    /// collector's safety depends on. A missing audit field degrades to
    /// `unknown`, because refusing to read a lease over incomplete provenance
    /// would make the collector fail, and a collector that cannot read a
    /// lease must abort rather than proceed: a lenient parse is what keeps a
    /// cosmetic gap from looking like a reason to delete. The project name
    /// and the renewal timestamp are not negotiable.
    ///
    /// # Errors
    ///
    /// [`ClientError::MalformedRoots`] when the body is not a JSON object,
    /// the project name is invalid, or the renewal time is missing or
    /// negative.
    pub fn parse(text: &str) -> Result<Self> {
        let value: serde_json::Value =
            serde_json::from_str(text).map_err(|_| ClientError::MalformedRoots)?;
        let raw = value.as_object().ok_or(ClientError::MalformedRoots)?;

        let project = raw
            .get("project")
            .and_then(serde_json::Value::as_str)
            .and_then(|text| ProjectName::parse(text).ok())
            .ok_or(ClientError::MalformedRoots)?;

        let renewed_at_ms = raw
            .get("renewedAtMs")
            .and_then(serde_json::Value::as_u64)
            .ok_or(ClientError::MalformedRoots)?;

        Ok(Self {
            project: project.as_str().to_string(),
            renewed_at_ms,
            repository: text_field(raw, "repository"),
            ref_: text_field(raw, "ref"),
            run_id: text_field(raw, "runId"),
            commit_sha: text_field(raw, "commitSha"),
            installables: list_field(raw, "installables"),
            store_paths: list_field(raw, "storePaths"),
        })
    }

    /// Whether the lease is recent enough to protect what it names at
    /// `now`. Computed forward from the renewal with a saturating clock
    /// delta, so a clock that jumped backwards makes a lease look more
    /// current rather than expired: the conservative direction for a
    /// decision that gates deletion.
    pub fn is_active(&self, now: UnixMillis, retention_ms: u64) -> bool {
        now.saturating_ms_since(UnixMillis::new(self.renewed_at_ms)) < retention_ms
    }
}

/// A field that must be a string, defaulting when absent so an older
/// document still reads.
fn text_field(raw: &serde_json::Map<String, serde_json::Value>, name: &str) -> String {
    raw.get(name)
        .and_then(serde_json::Value::as_str)
        .unwrap_or(UNKNOWN_CLAIM)
        .to_string()
}

/// A field that must be an array of strings, defaulting to empty.
fn list_field(raw: &serde_json::Map<String, serde_json::Value>, name: &str) -> Vec<String> {
    raw.get(name)
        .and_then(serde_json::Value::as_array)
        .map(|entries| {
            entries
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn body() -> String {
        serde_json::json!({
            "project": "my-org-my-repo",
            "renewedAtMs": 1_780_000_000_000_u64,
            "repository": "my-org/my-repo",
            "ref": "refs/heads/main",
            "runId": "123",
            "commitSha": "abc",
            "installables": [".#devShells.aarch64-darwin.default"],
            "storePaths": ["/nix/store/REDACTED.2"],
        })
        .to_string()
    }

    #[test]
    fn round_trip_preserves_every_field() {
        let document = LeaseDocument::parse(&body()).expect("a real document parses");
        let again = LeaseDocument::parse(&document.serialize()).expect("the own form parses");
        assert_eq!(document, again);
    }

    #[test]
    fn missing_provenance_defaults_to_unknown() {
        let sparse = r#"{"project":"my-org-my-repo","renewedAtMs":1780000000000}"#;
        let document = LeaseDocument::parse(sparse).expect("audit gaps degrade");
        assert_eq!(document.repository, "unknown");
        assert_eq!(document.commit_sha, "unknown");
        assert!(document.store_paths.is_empty());
    }

    #[test]
    fn project_and_renewal_are_not_negotiable() {
        for bad in [
            r#"{}"#,
            r#"{"project":42,"renewedAtMs":1}"#,
            r#"{"project":"a..b","renewedAtMs":1}"#,
            r#"{"project":"ok","renewedAtMs":-1}"#,
            r#"{"project":"ok","renewedAtMs":"1"}"#,
            r"[]",
        ] {
            assert!(LeaseDocument::parse(bad).is_err(), "{bad} refused");
        }
    }

    #[test]
    fn backwards_clock_keeps_a_lease_active() {
        let mut document = LeaseDocument::parse(&body()).expect("parses");
        document.renewed_at_ms = 1_780_000_000_000;
        // Reading the lease from one second in its past must not expire it.
        let behind = UnixMillis::new(document.renewed_at_ms - 1_000);
        assert!(document.is_active(behind, LEASE_RETENTION_MS));
        let beyond = UnixMillis::new(document.renewed_at_ms + LEASE_RETENTION_MS);
        assert!(!document.is_active(beyond, LEASE_RETENTION_MS));
    }
}

//! The generation document at `meta/generation`: the edge cache's global
//! epoch. Cache keys compose it, so one destructive sweep invalidates
//! every cached object within the document's own edge TTL. It lives in R2
//! with everything else, so it can corrupt like anything else, and the
//! read path treats corruption as "no edge caching this request" rather
//! than as a generation to trust: never assume zero.

use crate::constants::GENERATION_DOCUMENT_BYTES_MAX;

/// The document's parse failure. Not a client error: the document is
/// internal state, and its reader decides how to degrade.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GenerationCorrupt;

/// The generation document.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct GenerationDocument {
    /// The monotonic edge-caching epoch. Absent on disk means zero.
    pub generation: u64,
    /// When the last destructive sweep bumped it, in epoch milliseconds.
    #[serde(rename = "bumpedAtMs")]
    pub bumped_at_ms: u64,
}

impl GenerationDocument {
    /// The document an empty bucket starts from.
    pub const ZERO: Self = Self {
        generation: 0,
        bumped_at_ms: 0,
    };

    /// Serialize with a trailing newline, the shape the first cachet
    /// deployment wrote.
    pub fn serialize(&self) -> String {
        let mut body = serde_json::to_string(self).expect("numeric fields");
        body.push('\n');
        body
    }

    /// Parse the document, bounded before reading: a well-formed document
    /// is under a hundred bytes, so anything approaching the cap is
    /// corrupt without ever reaching the parser.
    ///
    /// # Errors
    ///
    /// [`GenerationCorrupt`] over the byte cap, on invalid JSON, or on a
    /// missing or non-numeric field.
    pub fn parse(text: &str) -> std::result::Result<Self, GenerationCorrupt> {
        if u64::try_from(text.len()).expect("len fits") > GENERATION_DOCUMENT_BYTES_MAX {
            return Err(GenerationCorrupt);
        }
        serde_json::from_str(text).map_err(|_| GenerationCorrupt)
    }

    /// The document after one destructive sweep.
    pub fn bump(&self, now_ms: u64) -> Self {
        Self {
            generation: self.generation + 1,
            bumped_at_ms: now_ms,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let document = GenerationDocument {
            generation: 7,
            bumped_at_ms: 1_780_000_000_000,
        };
        assert_eq!(GenerationDocument::parse(&document.serialize()), Ok(document));
    }

    #[test]
    fn corrupt_documents_are_typed() {
        for text in ["", "not json", "{}", "{\"generation\":\"7\"}", &"x".repeat(300)] {
            assert_eq!(GenerationDocument::parse(text), Err(GenerationCorrupt));
        }
    }
}

//! The multipart bookkeeping record at `uploads/{uploadId}`: the server's
//! copy of the part plan and the declared total. `resumeMultipartUpload`
//! carries no state, so part sizes are verified against this document, and
//! completion verifies the assembled byte count against it, which is the
//! only reason a part-number collision cannot silently corrupt an object.

use crate::constants::UPLOAD_STALE_MAX_MS;
use crate::types::UnixMillis;

/// The bookkeeping record for one in-flight multipart upload.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct UploadRecord {
    /// The destination bucket key of the object being assembled.
    pub key: String,
    /// The client-declared total size of the object.
    #[serde(rename = "totalBytes")]
    pub total_bytes: u64,
    /// The number of parts the plan expects, from `plan_shape`.
    #[serde(rename = "expectedParts")]
    pub expected_parts: u64,
    /// When the upload was created, in epoch milliseconds.
    #[serde(rename = "createdAtMs")]
    pub created_at_ms: u64,
}

impl UploadRecord {
    /// Serialize with a trailing newline.
    pub fn serialize(&self) -> String {
        let mut body = serde_json::to_string(self).expect("string and numeric fields");
        body.push('\n');
        body
    }

    /// Parse a stored record. Internal state, so a parse failure is the
    /// caller's storage error, not a client error.
    ///
    /// # Errors
    ///
    /// [`serde_json::Error`] on invalid JSON or a schema mismatch.
    pub fn parse(text: &str) -> std::result::Result<Self, serde_json::Error> {
        serde_json::from_str(text)
    }

    /// Whether the upload has been idle long enough to reap.
    pub fn is_stale(&self, now: UnixMillis) -> bool {
        now.saturating_ms_since(UnixMillis::new(self.created_at_ms)) > UPLOAD_STALE_MAX_MS
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let record = UploadRecord {
            key: format!("nar/{}.nar.zst", "x".repeat(52)),
            total_bytes: 3_000,
            expected_parts: 2,
            created_at_ms: 1_780_000_000_000,
        };
        assert_eq!(
            UploadRecord::parse(&record.serialize()).expect("the own form parses"),
            record
        );
    }

    #[test]
    fn staleness_uses_a_forward_delta() {
        let record = UploadRecord {
            key: String::new(),
            total_bytes: 1,
            expected_parts: 1,
            created_at_ms: 1_000,
        };
        assert!(!record.is_stale(UnixMillis::new(500)));
        assert!(record.is_stale(UnixMillis::new(1_000 + UPLOAD_STALE_MAX_MS + 1)));
    }
}

//! The `POST /roots/{project}` request body: the store paths a project is
//! keeping alive plus the installables that produced them. Bounded before
//! parsing, and every entry validated, because this body becomes the
//! collector's root set and anything in it must already be grammar-clean.

use crate::constants::{ROOTS_BODY_BYTES_MAX, ROOTS_PATHS_MAX};
use crate::error::{ClientError, Result};
use crate::keys::parse_store_path;

/// A validated roots payload.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RootsPayload {
    /// Full nix store paths, each grammar-validated.
    pub store_paths: Vec<String>,
    /// Flake installables the job built. Never begins with `-`: an
    /// installable is passed to `nix build` as an argv entry by the
    /// deployment's verification tooling, and a dash-prefixed entry would
    /// read as a command-line flag rather than a flake reference.
    pub installables: Vec<String>,
}

/// Parse a roots payload.
///
/// # Errors
///
/// [`ClientError::BodyTooLarge`] over the byte cap;
/// [`ClientError::MalformedRoots`] for anything else.
pub fn parse_roots_payload(text: &str) -> Result<RootsPayload> {
    if u64::try_from(text.len()).expect("len fits") > ROOTS_BODY_BYTES_MAX {
        return Err(ClientError::BodyTooLarge);
    }
    let value: serde_json::Value =
        serde_json::from_str(text).map_err(|_| ClientError::MalformedRoots)?;
    let raw = value.as_object().ok_or(ClientError::MalformedRoots)?;

    let store_paths = string_list(raw.get("storePaths"), "storePaths")?;
    let installables = string_list(raw.get("installables"), "installables")?;

    for installable in &installables {
        if installable.starts_with('-') {
            return Err(ClientError::MalformedRoots);
        }
    }
    for path in &store_paths {
        parse_store_path(path).map_err(|_| ClientError::MalformedRoots)?;
    }
    Ok(RootsPayload {
        store_paths,
        installables,
    })
}

/// Read one array-of-strings field, capped and element-validated.
fn string_list(raw: Option<&serde_json::Value>, _field: &'static str) -> Result<Vec<String>> {
    let Some(array) = raw.and_then(serde_json::Value::as_array) else {
        return Err(ClientError::MalformedRoots);
    };
    if array.len() > ROOTS_PATHS_MAX {
        return Err(ClientError::MalformedRoots);
    }
    let mut out = Vec::with_capacity(array.len());
    for entry in array {
        let Some(text) = entry.as_str() else {
            return Err(ClientError::MalformedRoots);
        };
        out.push(text.to_string());
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    const PATH: &str = "/nix/store/REDACTED.2";

    #[test]
    fn the_happy_document() {
        let body = serde_json::json!({
            "storePaths": [PATH],
            "installables": [".#devShells.aarch64-darwin.default"],
        })
        .to_string();
        let payload = parse_roots_payload(&body).expect("the contract parses");
        assert_eq!(payload.store_paths, [PATH]);
    }

    #[test]
    fn hostile_entries_are_refused() {
        for body in [
            r"{}",
            r#"{"storePaths": []}"#,
            &serde_json::json!({"storePaths": ["/etc/passwd-name"]}).to_string(),
            &serde_json::json!({"storePaths": [], "installables": ["--option substitute true"]})
                .to_string(),
            &serde_json::json!({"storePaths": [PATH, PATH], "installables": null}).to_string(),
        ] {
            assert!(parse_roots_payload(body).is_err(), "{body} refused");
        }
    }

    #[test]
    fn overlong_bodies_are_refused_by_size() {
        let huge = format!("{{\"storePaths\": [\"{}\"]}}", PATH.repeat(20_000));
        assert_eq!(parse_roots_payload(&huge), Err(ClientError::BodyTooLarge));
    }
}

