    );
    let blob: Box<Zeroizing<[u8; 64]>> = match <[u8; 64]>::try_from(&blob[..]) {
        Ok(arr) => Box::new(Zeroizing::new(arr)),
        Err(_) => return Err(KeyError::Length),
    };
    let signing = ed25519_dalek::SigningKey::from_bytes(
        <&[u8; 32]>::try_from(&blob[..32]).expect("slice of 64"),
