    let key = rsa::RsaPublicKey::new(
        rsa::BigUint::from_bytes_be(&n_bytes),
        rsa::BigUint::from_bytes_be(&e_bytes),
    )
    .map_err(|_| JwtError::KeyMaterial)?;
    let signature = rsa::pss::Signature::try_from(signature).map_err(|_| JwtError::Signature)?;
    let scheme = rsa::Pkcs1v15Sign::new::<sha2::Sha256>();
    Ok(rsa::signature::Verifier::verify(&key, signing_input.as_bytes(), &signature).is_ok())
}

