pub fn finish(&mut self) -> Result<(), ZstdError> {
    self.closed = true;
    self.push(&[])?;
    let decoder = self.decoder.as_mut().expect("decoder built in push");
    if !decoder.is_finished() {
        return Err(ZstdError::Truncated);
