{
  "name": "cachet-workerd",
  "private": true,
  "version": "0.0.1",
  "type": "module",
  "description": "The workerd lane's harness: the built worker running in miniflare against real R2 and Cache API semantics.",
  "dependencies": {
    "miniflare": "4.20251112.0"
  }
}

// The workerd lane's harness (docs/testing/workerd.md): the built worker
// runs in miniflare against workerd's real R2 and Cache API semantics, and
// the assertions cover the read path's contracts: handshake, grammar
// rejections, edge caching (positive and negative), HEAD behavior, and the
// generation document's corruption bypass. The work's logs are the seam
// for the latter three: the service emits read.edge_hit, read.bucket_hit,
// and read.miss, so caching behavior is observable without introspecting
// miniflare internals.
//
// Usage: WORKERD_NODE_MODULES=<path> node workerd/run.mjs <worker-build dir> <fixtures dir>

import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const [buildDir, fixturesDir] = process.argv.slice(2);
if (!buildDir || !fixturesDir) {
  console.error('usage: run.mjs <worker-build dir> <fixtures dir>');
  process.exit(2);
}

const nodeModules = process.env.WORKERD_NODE_MODULES;
if (!nodeModules) {
  console.error('WORKERD_NODE_MODULES must name the lane dependencies');
  process.exit(2);
}
const { Miniflare, Log } = await import(
  pathToFileURL(path.join(nodeModules, 'miniflare', 'dist', 'src', 'index.js')).href
);

// The worker's console output, captured line by line; the caching
// assertions read it.
const lines = [];
class CaptureLog extends Log {
  log(level, message) {
    lines.push(String(message));
  }
  logWithLevel(level, message) {
    lines.push(String(message));
  }
  error(message) {
    lines.push(String(message));
  }
}
const workerEvents = () => lines.join('\n');
const clearEvents = () => lines.splice(0, lines.length);

async function boot() {
  return new Miniflare({
    log: new CaptureLog(),
    modules: true,
    scriptPath: path.join(buildDir, 'index.js'),
    modulesRules: [{ type: 'CompiledWasm', include: ['**/*.wasm'], fallthrough: true }],
    compatibilityDate: '2025-09-01',
    r2Buckets: ['CACHE_BUCKET'],
  });
}

// waitUntil-driven cache puts race the next assertion; give the isolate a
// turn to drain them.
const settle = () => new Promise((resolve) => setTimeout(resolve, 100));

const results = [];
async function check(name, fn) {
  try {
    await fn();
    results.push(['ok', name]);
  } catch (failure) {
    results.push(['FAIL', `${name}: ${failure.message}`]);
  }
}

const NARINFO_KEY = 'qvqa04f0m85m0a6xxnan5vxnwg2jkgl9.narinfo';
const NAR_KEY = 'nar/11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst';

// Run one scenario against a fresh workerd: fresh R2, fresh edge cache.
async function scenario(name, seed, assertions) {
  const mf = await boot();
  try {
    clearEvents();
    const bucket = await mf.getR2Bucket('CACHE_BUCKET');
    await seed(bucket, mf);
    await assertions(mf);
  } finally {
    await mf.dispose();
  }
  process.stdout.write(`scenario ${name} done\n`);
}

await scenario('the read path serves and caches', async (bucket) => {
  const narinfo = await readFile(path.join(fixturesDir, NARINFO_KEY));
  const nar = await readFile(path.join(fixturesDir, '11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst'));
  await bucket.put(NARINFO_KEY, narinfo);
  await bucket.put(NAR_KEY, nar);
}, async (mf) => {
  const base = 'http://localhost';

  await check('GET /nix-cache-info answers the handshake', async () => {
    const res = await mf.dispatchFetch(`${base}/nix-cache-info`);
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('content-type'), 'text/x-nix-cache-info');
    assert.equal(res.headers.get('cache-control'), 'public, max-age=300');
    assert.equal(
      await res.text(),
      'StoreDir: /nix/store\nWantMassQuery: 1\nPriority: 30\n'
    );
  });

  await check('a seeded narinfo serves with the wire headers', async () => {
    const res = await mf.dispatchFetch(`${base}/${NARINFO_KEY}`);
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('content-type'), 'text/x-nix-narinfo');
    assert.equal(res.headers.get('cache-control'), 'public, max-age=2592000, immutable');
    const body = await res.text();
    assert.equal(body, await readFile(path.join(fixturesDir, NARINFO_KEY), 'utf8'));
    assert.equal(
      Number(res.headers.get('content-length')),
      Buffer.byteLength(body)
    );
  });

  await check('the second get comes from the edge', async () => {
    clearEvents();
    const res = await mf.dispatchFetch(`${base}/${NARINFO_KEY}`);
    assert.equal(res.status, 200);
    await settle();
    assert.match(workerEvents(), /"event":"read\.edge_hit"/);
    assert.doesNotMatch(workerEvents(), /"event":"read\.bucket_hit"/);
  });

  await check('a missing narinfo is a cacheable 404', async () => {
    const res = await mf.dispatchFetch(
      `${base}/33333333333333333333333333333333.narinfo`
    );
    assert.equal(res.status, 404);
    assert.equal(res.headers.get('content-type'), 'text/plain; charset=utf-8');
    assert.equal(res.headers.get('cache-control'), 'public, max-age=30');
    assert.equal(await res.text(), 'not found\n');
    await settle();
  });

  await check('the missing narinfo answers from the edge the second time', async () => {
    clearEvents();
    const res = await mf.dispatchFetch(
      `${base}/33333333333333333333333333333333.narinfo`
    );
    assert.equal(res.status, 404);
    await settle();
    assert.match(workerEvents(), /"event":"read\.edge_hit"/);
    assert.doesNotMatch(workerEvents(), /"event":"read\.miss"/);
  });

  await check('HEAD answers from bucket metadata alone', async () => {
    const res = await mf.dispatchFetch(`${base}/${NARINFO_KEY}`, { method: 'HEAD' });
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('content-type'), 'text/x-nix-narinfo');
    assert.equal(await res.text(), '');
  });

  await check('HEAD on a miss is an empty 404', async () => {
    const res = await mf.dispatchFetch(
      `${base}/44444444444444444444444444444444.narinfo`,
      { method: 'HEAD' }
    );
    assert.equal(res.status, 404);
    assert.equal(await res.text(), '');
  });

  await check('a NAR streams with its wire headers', async () => {
    const res = await mf.dispatchFetch(`${base}/${NAR_KEY.replace('nar/', 'nar/')}`);
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('content-type'), 'application/x-nix-nar');
    assert.equal(res.headers.get('cache-control'), 'public, max-age=2592000, immutable');
    const bytes = Buffer.from(await res.arrayBuffer());
    const seeded = await readFile(
      path.join(fixturesDir, '11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst')
    );
    assert.deepEqual(bytes, seeded);
  });

  await check('a shapeless path is a problem 404', async () => {
    const res = await mf.dispatchFetch(`${base}/hello`);
    assert.equal(res.status, 404);
    assert.equal(res.headers.get('content-type'), 'application/problem+json');
    const body = await res.json();
    assert.equal(body.code, 'not_found');
    assert.equal(body.status, 404);
  });

  await check('a grammar-broken narinfo path is a problem 400', async () => {
    const res = await mf.dispatchFetch(`${base}/notahash.narinfo`);
    assert.equal(res.status, 400);
    assert.equal(res.headers.get('content-type'), 'application/problem+json');
    const body = await res.json();
    assert.equal(body.code, 'malformed_key');
    assert.equal(body.status, 400);
  });

  await check('POST is not a read', async () => {
    const res = await mf.dispatchFetch(`${base}/${NARINFO_KEY}`, { method: 'POST' });
    assert.equal(res.status, 404);
  });
});

await scenario(
  'a corrupt generation document bypasses the edge',
  async (bucket) => {
    const narinfo = await readFile(path.join(fixturesDir, NARINFO_KEY));
    await bucket.put(NARINFO_KEY, narinfo);
    await bucket.put('meta/generation', 'this was never json');
  },
  async (mf) => {
    await check('the service degrades to bucket reads', async () => {
      const first = await mf.dispatchFetch(`http://localhost/${NARINFO_KEY}`);
      assert.equal(first.status, 200);
      await settle();
      clearEvents();
      const second = await mf.dispatchFetch(`http://localhost/${NARINFO_KEY}`);
      assert.equal(second.status, 200);
      await settle();
      assert.match(workerEvents(), /"event":"generation\.document_corrupt"/);
      assert.match(workerEvents(), /"event":"read\.bucket_hit"/);
      assert.doesNotMatch(workerEvents(), /"event":"read\.edge_hit"/);
    });
  }
);

let failed = 0;
for (const [status, name] of results) {
  if (status === 'ok') {
    process.stdout.write(`ok ${name}\n`);
  } else {
    failed += 1;
    process.stdout.write(`FAIL ${name}\n`);
  }
}
if (failed > 0) {
  process.stdout.write(`${failed} workerd assertion(s) failed\n`);
  process.exit(1);
}
process.stdout.write('workerd lane green\n');

