#[test]
fn problem_bodies_are_byte_locked() {
    insta::assert_snapshot!(
        cachet_core::problem::problem_body(ClientError::MalformedKey),
        @"{\"type\":\"about:blank\",\"status\":400,\"title\":\"key grammar rejected\",\"code\":\"malformed_key\"}\n"
