import { fail, ok, type Result } from '../result.js';
import type { NarKey, UnixMillis } from '../types.js';

/**
 * What the Worker records when a multipart upload begins.
 *
 * Stored under `uploads/{uploadId}`, which is a reserved prefix no client request can reach.
 */
export interface UploadRecord {
    readonly key: NarKey;
    /** The total the client declared up front, which fixes every part's expected size. */
    readonly totalBytes: number;
    readonly expectedParts: number;
    /** So the collector can reclaim an upload that was abandoned. */
    readonly createdAtMs: UnixMillis;
}

/** One completed part, as the client reports it back. */
export interface CompletedPart {
    readonly partNumber: number;
    readonly etag: string;
}

/**
 * How many parts a declared total needs, and how large the last one is.
 *
 * Every part but the last is exactly {@link UPLOAD_PART_BYTES}; the last is the remainder. Deriving
 * the plan from the total — rather than letting a client choose part sizes — is what makes R2's
 * uniformity rule satisfied by construction rather than by hope.
 */
export function planParts(
    totalBytes: number,
): Result<{ expectedParts: number; finalPartBytes: number }> {
    if (!Number.isSafeInteger(totalBytes) || totalBytes <= 0) {
        return fail('body_too_large', 'a multipart upload declares a positive total size');
    }

    const expectedParts = Math.ceil(totalBytes / UPLOAD_PART_BYTES);
    if (expectedParts > MULTIPART_PARTS_MAX) {
        return fail(
            'body_too_large',
            `an object of ${String(totalBytes)} bytes needs more than ${String(MULTIPART_PARTS_MAX)} parts`,
        );
    }

    const finalPartBytes = totalBytes - (expectedParts - 1) * UPLOAD_PART_BYTES;
    assert(finalPartBytes > 0, 'the final part carries at least one byte');
    assert(finalPartBytes <= UPLOAD_PART_BYTES, 'the final part is no larger than a full part');
    return ok({ expectedParts, finalPartBytes });
}

/** The size a given part must be, exactly. */
export function expectedPartBytes(record: UploadRecord, partNumber: number): number {
    assert(partNumber >= 1, 'a part number is one-based');
    assert(partNumber <= record.expectedParts, 'a part number is within the plan');
    return partNumber === record.expectedParts
        ? record.totalBytes - (record.expectedParts - 1) * UPLOAD_PART_BYTES
        : UPLOAD_PART_BYTES;
}

/**
 * Validate one part before it is stored.
 *
 * The bookkeeping record exists for this size check: catching a wrong-sized part here
 * costs the client one request, where catching it at `complete` costs the entire upload.
 */
export function checkPart(
    record: UploadRecord,
    partNumber: number,
    lengthBytes: number,
): Result<void> {
    if (!Number.isSafeInteger(partNumber) || partNumber < 1 || partNumber > record.expectedParts) {
        return fail(
            'part_number_invalid',
            `a part number is between 1 and ${String(record.expectedParts)}`,
        );
    }

    const expected = expectedPartBytes(record, partNumber);
    if (lengthBytes !== expected) {
        return fail(
            'part_size_mismatch',
            `part ${String(partNumber)} must be exactly ${String(expected)} bytes, not ${String(lengthBytes)}`,
