}

/** One entry of a completion body. */
function parseCompletedPart(entry: unknown): Result<CompletedPart> {
    if (typeof entry !== 'object' || entry === null) {
        return fail('complete_parts_mismatch', 'each part is an object');
    }
    const raw = entry as { partNumber?: unknown; etag?: unknown };
    if (typeof raw.partNumber !== 'number' || !Number.isSafeInteger(raw.partNumber)) {
        return fail('complete_parts_mismatch', 'each part has an integer partNumber');
    }
    if (typeof raw.etag !== 'string' || raw.etag.length === 0) {
        return fail('complete_parts_mismatch', 'each part has a non-empty etag');
    }
    return ok({ partNumber: raw.partNumber, etag: raw.etag });
}

/** Serialise the bookkeeping record. */
export function serializeUploadRecord(record: UploadRecord): string {
    return `${JSON.stringify({
        key: String(record.key),
        totalBytes: record.totalBytes,
        expectedParts: record.expectedParts,
        createdAtMs: Number(record.createdAtMs),
    })}\n`;
}

/**
 * Parse the bookkeeping record.
 *
 * Defensive, and validated against the key the request named: a record whose key does not match is
 * refused rather than trusted, so a client cannot present one upload's id while writing to another
 * object's key.
 */
export function parseUploadRecord(text: string, expectedKey: NarKey): Result<UploadRecord> {
    if (text.length > UPLOAD_RECORD_BYTES_MAX) {
        return fail('upload_unknown', 'the upload record is implausibly large');
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(text);
    } catch {
        return fail('upload_unknown', 'the upload record is not valid JSON');
    }
    if (typeof parsed !== 'object' || parsed === null) {
        return fail('upload_unknown', 'the upload record is not an object');
    }

    const raw = parsed as {
        key?: unknown;
        totalBytes?: unknown;
        expectedParts?: unknown;
        createdAtMs?: unknown;
    };
    if (raw.key !== String(expectedKey)) {
        // why: the upload id is a bearer token for one key. Without this check, presenting a valid
        // id on a different key's route would let a client append parts to an object they were not
        // uploading.
        return fail('upload_unknown', 'the upload record names a different key');
    }
    if (
        typeof raw.totalBytes !== 'number' ||
        typeof raw.expectedParts !== 'number' ||
        typeof raw.createdAtMs !== 'number' ||
        !Number.isSafeInteger(raw.totalBytes) ||
        !Number.isSafeInteger(raw.expectedParts) ||
        !Number.isSafeInteger(raw.createdAtMs)
    ) {
        return fail('upload_unknown', 'the upload record is malformed');
    }

    return ok({
        key: expectedKey,
        totalBytes: raw.totalBytes,
        expectedParts: raw.expectedParts,
        createdAtMs: raw.createdAtMs as UnixMillis,
    });
}

/**
 * Whether an in-flight upload is old enough to reclaim.
 *
 * An abandoned upload holds storage and a bookkeeping object. The window is far longer than any CI
 * job, so the collector can abort stale uploads with no risk of interrupting one in progress.
 */
export function isStaleUpload(
    record: UploadRecord,
    nowMs: UnixMillis,
    staleAfterMs: number,
): boolean {
    return nowMs - record.createdAtMs >= staleAfterMs;
}
