        doc.file_hash = Some(format!("sha256:{}", "w".repeat(52)));
        assert_eq!(
            VerifiedNar::verify(doc, 12, "sha256:0iqi0", &"g".repeat(52), 42),
            Err(ClientError::FileHashMismatch)
        );
