    env: &Env,
    now: UnixMillis,
    req: &Request,
) -> cachet_core::error::Result<cachet_core::auth::OidcIdentity> {
    let header = req
        .headers()
        .get("authorization")
        .map_err(|_| ClientError::MalformedAuth)?;
    auth::authorize_write(env, now, header.as_deref()).await
}

