        },
    };

    // An unknown kid means the issuer rotated since the cache entry: one
    // refetch, never a loop.
    let mut find = |kid: Option<&str>, keys: &[RsaJwk]| {
        kid.and_then(|kid| keys.iter().find(|key| key.kid == kid).cloned())
    };
    if let Some(key) = find(kid, &keys) {
        return Ok(key);
    }
    if refetch_once_allowed(refetched) {
        refetched = true;
        keys = fetch_jwks(env).await.map_err(|_| ClientError::Unauthorized)?;
        JWKS_CACHE.with(|slot| {
            *slot.borrow_mut() = Some((now.as_u64(), keys.clone()));
        });
        if let Some(key) = find(kid, &keys) {
            return Ok(key);
        }
    }
    Err(ClientError::Unauthorized)
}

