    ),
    responses(
        (status = 204, description = "The lease renewed"),
        (status = 400, description = "problem+json; code=malformed_key or malformed_roots", body = ProblemBody),
        (status = 401, description = "problem+json; code=unauthorized", body = ProblemBody),
        (status = 403, description = "problem+json; code=forbidden_org, forbidden_ref, or forbidden_project", body = ProblemBody),
        (status = 411, description = "problem+json; code=length_required", body = ProblemBody),
        (status = 413, description = "problem+json; code=body_too_large", body = ProblemBody),
        (status = 503, description = "problem+json; code=auth_unavailable or storage_unavailable", body = ProblemBody),
    )
)]
pub fn lease_renew() {}

/// `PUT /nar/{key}`: a whole NAR in one request, up to the single-PUT
/// cap. Larger uploads use the multipart quartet below.
#[utoipa::path(
    put,
    path = "/nar/{key}",
    params(
        ("key" = String, Path, description = "The NAR object key: sha256 nix base32 with an optional compression suffix"),
    ),
    request_body(
        description = "The NAR bytes; the key names their sha256, so the content is self-addressing",
        content_type = "application/x-nix-nar",
        content = String,
    ),
    responses(
        (status = 204, description = "Stored"),
        (status = 400, description = "problem+json; code=malformed_key", body = ProblemBody),
