        (status = 403, description = "problem+json; code=forbidden_org", body = ProblemBody),
        (status = 411, description = "problem+json; code=length_required", body = ProblemBody),
        (status = 413, description = "problem+json; code=body_too_large", body = ProblemBody),
        (status = 503, description = "problem+json; code=auth_unavailable or storage_unavailable", body = ProblemBody),
    )
)]
pub fn nar_put() {}

/// `POST /nar/{key}?uploads`: begin a multipart upload. The
/// `x-cachet-upload-bytes` header declares the total size and binds the
/// upload's part plan.
#[utoipa::path(
    post,
    path = "/nar/{key}",
    params(
        ("key" = String, Path, description = "The NAR object key"),
        ("uploads" = bool, Query, description = "Creates a multipart upload"),
        ("x-cachet-upload-bytes" = String, Header, description = "The declared total size in bytes"),
    ),
    responses(
        (status = 200, description = "The upload id", body = UploadCreated),
        (status = 400, description = "problem+json; code=malformed_key", body = ProblemBody),
        (status = 401, description = "problem+json; code=unauthorized", body = ProblemBody),
        (status = 403, description = "problem+json; code=forbidden_org", body = ProblemBody),
        (status = 411, description = "problem+json; code=length_required", body = ProblemBody),
        (status = 413, description = "problem+json; code=body_too_large", body = ProblemBody),
        (status = 503, description = "problem+json; code=auth_unavailable or storage_unavailable", body = ProblemBody),
    )
)]
