163	/// The destructive plan: ordered, explicit, and empty whenever a gate
164	/// tripped. Execution deletes `narinfo_deletes` first, so at every instant
165	/// the cache serves a subset of a coherent earlier state.
166	#[derive(Debug, Clone, Default, PartialEq, Eq)]
167	pub struct DeletionPlan {
168	    /// Narinfo keys to delete, all of them before any NAR.
169	    pub narinfo_deletes: Vec<String>,
170	    /// NAR keys to delete after every narinfo is gone.
171	    pub nar_deletes: Vec<String>,
172	    /// The gate that aborted planning, if any. A tripped plan is always
173	    /// empty; the report records the trip.
174	    pub gate: Option<GateTrip>,
175	}
176	
177	/// Decide the destructive plan.
178	///
179	/// Candidates are narinfo objects that are unmarked and older than the
180	/// grace window. NAR deletions resolve from the candidate narinfos' own
181	/// URLs minus every URL a marked narinfo still names, so a NAR shared
182	/// between a live and a dead path survives. The fraction gate compares
183	/// candidate count against the full narinfo inventory: a run that would
184	/// empty the cache is refused outright.
185	pub fn plan_deletions(
186	    inventory: &[InventoryItem],
187	    marked: &BTreeSet<StorePathHash>,
188	    marked_urls: &BTreeMap<StorePathHash, NarKey>,
189	    candidate_urls: &[(StorePathHash, NarKey)],
190	    now: UnixMillis,
191	    grace_ms: u64,
192	) -> DeletionPlan {
193	    let mut plan = DeletionPlan::default();
194	
195	    let mut narinfo_inventory = 0usize;
196	    let mut narinfo_deletes = Vec::new();
197	    for item in inventory {
198	        if is_reserved_key(&item.key) {
199	            continue;
200	        }
201	        if item.key.ends_with(crate::constants::NARINFO_KEY_SUFFIX) {
202	            let Ok(hash) = StorePathHash::parse(
203	                &item.key[..item.key.len() - crate::constants::NARINFO_KEY_SUFFIX.len()],
204	            ) else {
205	                // Unnameable narinfo-shaped object: it cannot map to a
206	                // lease-protected path either way, so plan says nothing and
207	                // the report's gate list has it noted by the driver.
208	                continue;
209	            };
210	            narinfo_inventory += 1;
211	            if !marked.contains(&hash)
212	                && now.saturating_ms_since(UnixMillis::new(item.uploaded_at_ms)) > grace_ms
213	            {
214	                narinfo_deletes.push(item.key.clone());
215	            }
216	        }
217	    }
218	    narinfo_deletes.sort();
219	
220	    // why: the fraction gate compares in integers, not floats: usize→f64
221	    // casts lose precision at pathological cache sizes, and a safety gate
222	    // must never silently widen.
223	    if narinfo_deletes.len() * SWEEP_MAX_FRACTION_DENOMINATOR
224	        > narinfo_inventory * SWEEP_MAX_FRACTION_NUMERATOR
225	    {
226	        plan.gate = Some(GateTrip::SweepFractionExceeded {
227	            deletions: narinfo_deletes.len(),
228	            inventory: narinfo_inventory,
229	        });
230	        return plan;
231	    }
232	    plan.narinfo_deletes = narinfo_deletes;
233	
234	    let live_urls: BTreeSet<&str> = marked_urls.values().map(NarKey::as_str).collect();
235	    let mut nar_deletes: Vec<String> = candidate_urls
236	        .iter()
237	        .filter(|(_, url)| !live_urls.contains(url.as_str()))
238	        .map(|(_, url)| url.as_str().to_string())
239	        .collect();
240	    nar_deletes.sort();
241	    nar_deletes.dedup();
242	    plan.nar_deletes = nar_deletes;
243	
244	    plan
245	}
