//! The cron-driven collector. cachet-core decides everything destructive
//! as data (the walk, the gates, the plan, the report); this module
//! enumerates, reads, walks, deletes, and reports against the real
//! bucket, persisting `meta/gc-cursor` at each stage boundary so a cache
//! of any size sweeps across ticks inside one binding's limits.
//!
//! Resume semantics: inventory and leases recompute every tick (they are
//! listing-bounded and cheap), while the mark, candidate, and sweep
//! stages freeze into the cursor. Frozen marks only ever over-protect a
//! path relative to the newer inventory, which is the safe direction for
//! a deletion system.
//!
//! Budget accounting: every binding call spends one operation against
//! [`GC_OP_BUDGET`], and the wall clock answers to [`GC_HEADROOM_MS`];
//! either limit hit freezes the run with nothing half-applied, because
//! the deletion plan itself is persisted and its execution is ordered and
//! idempotent.

use cachet_core::constants::{
    BUCKET_LIST_PAGE_LIMIT, GC_CURSOR_OBJECT_KEY, GC_DELETE_BATCH, GC_HEADROOM_MS, GC_OP_BUDGET,
    GC_REPORTS_KEY_PREFIX, GC_RUNS_KEY_PREFIX, GC_RUNS_RETENTION_MS, GENERATION_OBJECT_KEY,
    ROOTS_KEY_PREFIX, UPLOADS_KEY_PREFIX, UPLOAD_STALE_MAX_MS,
};
use cachet_core::error::ClientError;
use cachet_core::gc::{
    ClosureWalker, GcCursor, GcReport, GcStage, InventoryItem, SweepCursor, WalkOutcome,
    WalkReadError, plan_deletions,
};
use cachet_core::generation::GenerationDocument;
use cachet_core::keys::{lease_key_for_project, project_from_lease_key};
use cachet_core::lease::LeaseDocument;
use cachet_core::narinfo::Narinfo;
use cachet_core::types::{ProjectName, StorePathHash, UnixMillis};
use cachet_core::upload_record::UploadRecord;
use worker::{Bucket, Env, Result};

use crate::log;

/// One invocation's spend: binding calls and wall time, each with its
/// honest ceiling.
struct Budget {
    ops: u64,
    started_at_ms: u64,
}

impl Budget {
    fn new(started_at_ms: u64) -> Self {
        Self {
            ops: 0,
            started_at_ms,
        }
    }

    fn spend(&mut self) {
        self.ops += 1;
    }

    /// Either ceiling hit: time to freeze cleanly.
    fn spent_out(&self, now_ms: u64) -> bool {
        self.ops >= GC_OP_BUDGET || now_ms.saturating_sub(self.started_at_ms) >= GC_HEADROOM_MS
    }
}

/// What a stage concluded: continue in this tick, or the run froze and
/// the invocation is done.
enum StageVerdict {
    Continue,
    Frozen,
}

/// The invocation's wall clock sample, taken at each check: the Clock
/// seam's scheduled-event instance (CLAUDE.md §3).
fn now_ms() -> u64 {
    worker::Date::now().as_millis()
}

fn bucket(env: &Env) -> Result<Bucket> {
    env.bucket("CACHE_BUCKET")
}

/// Whether the collector fires: armed unless the var explicitly says `0`.
fn armed(env: &Env) -> bool {
    env.var("CACHET_GC_ARMED")
        .map(|value| value.to_string() != "0")
        .unwrap_or(true)
}

/// The grace window in force, overridable per deployment for staging.
fn grace_window_ms(env: &Env) -> u64 {
    env.var("CACHET_GC_GRACE_MS")
        .ok()
        .and_then(|value| value.to_string().parse().ok())
        .unwrap_or(cachet_core::constants::GRACE_WINDOW_MS)
}

/// The run id: start time plus entropy, so artifacts sort in run order
/// and two runs can never collide.
fn run_id(started_at_ms: u64) -> String {
    let mut entropy = [0_u8; 8];
    getrandom::getrandom(&mut entropy).expect("getrandom cannot fail on workers");
    let hex: String = entropy.iter().map(|b| format!("{b:02x}")).collect();
    format!("{started_at_ms}-{hex}")
}

/// The scheduled entry point. Runs are quiet in every direction: the
/// run's facts live in its report and artifacts, and the event log names
/// only starts, pauses, gates, and finishes.
pub async fn drive(env: &Env) -> Result<()> {
    let start = now_ms();
    if !armed(env) {
        log::event("info", "gc.disarmed", &[]);
        return Ok(());
    }
    let grace_ms = grace_window_ms(env);
    let mut budget = Budget::new(start);
    let bucket = bucket(env)?;

    let mut run = match load_run(env, &bucket, &mut budget, start).await {
        Ok(run) => run,
        Err(failure) => {
            log::event(
                "error",
                "gc.cursor_read_failed",
                &[("error", failure.to_string())],
            );
            return Ok(());
        }
    };
    log::event(
        "info",
        "gc.run_started",
        &[
            ("runId", run.cursor.run_id.clone()),
            ("stage", stage_name(run.cursor.stage).to_string()),
        ],
    );

    // Inventory and leases recompute every tick; their outputs carry the
    // run in memory. A tick that resumes past them skips their stages.
    let mut inventory: Vec<InventoryItem> = Vec::new();
    let mut roots: Vec<StorePathHash> = Vec::new();

    if run.cursor.stage == GcStage::Inventory {
        match stage_inventory(env, &bucket, &mut budget, start).await {
            Ok(StageVerdict::Continue) => {
                inventory = stage_take_inventory(env, &bucket, &mut budget, start).await;
            }
            Ok(StageVerdict::Frozen) => return Ok(()),
            Err(failure) => {
                return abort_with_gate(env, &mut run, failure, &mut budget, start).await;
            }
        }
    }
    if run.cursor.stage == GcStage::Leases {
        match stage_leases(env, &bucket, &mut budget, start, &mut run).await {
            Ok((StageVerdict::Continue, found)) => {
                roots = found;
                let active = u64::try_from(roots.len()).unwrap_or(u64::MAX);
                run.cursor.active_leases = active;
            }
            Ok((StageVerdict::Frozen, _)) => return Ok(()),
            Err(failure) => {
                return abort_with_gate(env, &mut run, failure, &mut budget, start).await;
            }
        }
    }

    // The mark walk: resume a frozen walker or start from this tick's
    // roots. Marks outlive the tick through the cursor.
    let outcome = match stage_mark(env, &bucket, &mut budget, start, &mut run, &roots).await {
        Ok(StageVerdict::Continue) => run.outcome.take().expect("a finished mark has its outcome"),
        Ok(StageVerdict::Frozen) => return Ok(()),
        Err(failure) => {
            return abort_with_gate(env, &mut run, failure, &mut budget, start).await;
        }
    };
    if let Some(trip) = outcome.gate {
        return abort_with_gate(env, &mut run, trip_to_failure(&trip), &mut budget, start).await;
    }

    Ok(())
}

