//! The cron-driven collector. cachet-core decides everything destructive
//! as data (the walk, the gates, the plan, the report); this module
//! enumerates, reads, walks, deletes, and reports against the real
//! bucket, persisting `meta/gc-cursor` at each boundary so a cache of any
//! size sweeps across ticks inside one binding's limits.
//!
//! Resume semantics: inventory and leases recompute every tick (they are
//! listing-bounded and cheap, and one tick must fit their listings),
//! while the mark, collect, sweep, and report stages hold their frozen
//! state in the cursor. Frozen marks and a frozen plan only ever
//! over-protect a path relative to a newer inventory, which is the safe
//! direction for a deletion system; the exact grace boundary settles at
//! plan time and stays settled for the run.
//!
//! Budget accounting: every binding call spends one operation against
//! [`GC_OP_BUDGET`], and the wall clock answers to [`GC_HEADROOM_MS`].
//! Either limit hit freezes the run: the cursor already holds everything
//! the next tick needs, because deletion is ordered (narinfos before
//! NARs, always) and idempotent.

use std::collections::BTreeMap;

use cachet_core::constants::{
    BUCKET_LIST_PAGE_LIMIT, GC_CURSOR_OBJECT_KEY, GC_DELETE_BATCH, GC_HEADROOM_MS, GC_OP_BUDGET,
    GC_REPORTS_KEY_PREFIX, GC_RUNS_KEY_PREFIX, GC_RUNS_RETENTION_MS, GENERATION_OBJECT_KEY,
    ROOTS_KEY_PREFIX, UPLOAD_STALE_MAX_MS, UPLOADS_KEY_PREFIX,
};
use cachet_core::gc::{
    ClosureWalker, CollectCursor, GcCursor, GcReport, GcStage, GateTrip, InventoryItem,
    SweepCursor, WalkOutcome, WalkReadError, plan_deletions, sweep_candidates,
};
use cachet_core::generation::GenerationDocument;
use cachet_core::keys::project_from_lease_key;
use cachet_core::lease::LeaseDocument;
use cachet_core::narinfo::Narinfo;
use cachet_core::types::{StorePathHash, UnixMillis};
use cachet_core::upload_record::UploadRecord;
use worker::{Bucket, Env, Result};

use crate::log;

/// One invocation's spend: binding calls and wall time, each with its
/// honest ceiling.
struct Budget {
    ops: u64,
    started_at_ms: u64,
}

impl Budget {
    fn new(started_at_ms: u64) -> Self {
        Self {
            ops: 0,
            started_at_ms,
        }
    }

    fn spend(&mut self) {
        self.ops += 1;
    }

    /// Either ceiling hit: time to freeze cleanly.
    fn spent_out(&self, now_ms: u64) -> bool {
        self.ops >= GC_OP_BUDGET
            || now_ms.saturating_sub(self.started_at_ms) >= GC_HEADROOM_MS
    }

    /// The serialized counters the log line carries at pause and finish.
    fn fields(&self, run_id: &str, stage_content: &str) -> [(String, String); 3] {
        [
            ("runId".to_string(), run_id.to_string()),
            ("stage".to_string(), stage_content.to_string()),
            ("ops".to_string(), self.ops.to_string()),
        ]
    }
}

/// The invocation's wall clock, sampled at each check: the Clock seam's
/// scheduled-event instance (CLAUDE.md §3).
fn now_ms() -> u64 {
    worker::Date::now().as_millis()
}

/// Whether the collector fires: armed unless the var explicitly says `0`.
fn armed(env: &Env) -> bool {
    env.var("CACHET_GC_ARMED")
        .map(|value| value.to_string() != "0")
        .unwrap_or(true)
}

/// The grace window in force, overridable per deployment for staging.
fn grace_window_ms(env: &Env) -> u64 {
    env.var("CACHET_GC_GRACE_MS")
        .ok()
        .and_then(|value| value.to_string().parse().ok())
        .unwrap_or(cachet_core::constants::GRACE_WINDOW_MS)
}

/// The run id: start time plus entropy, so artifacts sort in run order
/// and no two runs can collide.
fn run_id(started_at_ms: u64) -> String {
    let mut entropy = [0_u8; 8];
    getrandom::getrandom(&mut entropy).expect("getrandom cannot fail on workers");
    let hex: String = entropy.iter().map(|b| format!("{b:02x}")).collect();
    format!("{started_at_ms}-{hex}")
}

fn stage_name(stage: GcStage) -> &'static str {
    match stage {
        GcStage::Inventory => "inventory",
        GcStage::Leases => "leases",
        GcStage::Mark => "mark",
        GcStage::Candidates => "candidates",
        GcStage::Sweep => "sweep",
        GcStage::Report => "report",
    }
}

/// Store the cursor. Freezes are loud in the log and silent in the
/// bucket: one put, no report, no artifacts; the run is not done, only
/// parked.
async fn freeze(bucket: &Bucket, budget: &mut Budget, cursor: &GcCursor) -> Result<()> {
    budget.spend();
    bucket
        .put(GC_CURSOR_OBJECT_KEY, cursor.serialize())
        .execute()
        .await?;
    log::event(
        "info",
        "gc.paused",
        &budget.fields(&cursor.run_id, stage_name(cursor.stage)),
    );
    Ok(())
}

/// The scheduled entry point. A run is quiet in every direction: its
/// facts live in its artifacts and report, and this module's event lines
/// name only starts, pauses, gates, and finishes.
pub async fn drive(env: &Env) -> Result<()> {
    let start = now_ms();
    if !armed(env) {
        log::event("info", "gc.disarmed", &[]);
        return Ok(());
    }
    let grace_ms = grace_window_ms(env);
    let mut budget = Budget::new(start);
    let bucket = env.bucket("CACHE_BUCKET")?;

    let mut cursor = match read_cursor(&bucket, &mut budget, start).await {
        Ok(cursor) => cursor,
        Err(failure) => {
            // A cursor that will not read must not block the collector
            // forever: the runs recompute, and deletion is what recompute
            // protects. Start over and say so.
            log::event(
                "error",
                "gc.cursor_corrupt",
                &[("error", failure.to_string())],
            );
            fresh_cursor(start)
        }
    };
    log::event(
        "info",
        "gc.run_started",
        &[
            ("runId", cursor.run_id.clone()),
            ("stage", stage_name(cursor.stage).to_string()),
        ],
    );

    // Inventory and leases recompute every tick that needs them: their
    // outputs drive the walk's roots and the candidates' ages.
    let needs_fresh = matches!(
        cursor.stage,
        GcStage::Inventory | GcStage::Leases | GcStage::Mark | GcStage::Candidates
    );
    let mut inventory: Vec<InventoryItem> = Vec::new();
    let mut roots: Vec<StorePathHash> = Vec::new();
    if needs_fresh {
        if budget.spent_out(now_ms()) {
            return freeze(&bucket, &mut budget, &cursor).await;
        }
        match stage_inventory(&bucket, &mut budget).await {
            Ok(items) => {
                cursor.inventory_paths = count_parseable_narinfos(&items);
                let gate_failure = |trip| {
                    let mut found = fresh_cursor(start);
                    found.run_id = cursor.run_id.clone();
                    gate_outcome(trip, &mut found)
                };
                inventory = items;
                drop(gate_failure);
            }
            Err(trip) => return gate_abort(&bucket, &mut budget, cursor, trip, 0, 0).await,
        }
        cursor.stage = GcStage::Leases;
        if budget.spent_out(now_ms()) {
            return freeze(&bucket, &mut budget, &cursor).await;
        }
        match stage_leases(&bucket, &mut budget, start).await {
            Ok(found) => {
                cursor.active_leases = u64::try_from(found.len()).unwrap_or(u64::MAX);
                roots = found;
            }
            Err(trip) => return gate_abort(&bucket, &mut budget, cursor, trip, 0, 0).await,
        }
        cursor.stage = GcStage::Mark;
    }

    // The walk: resume a frozen frontier, or start from this tick's roots
    // and freeze into existence as it goes.
    let mut walker = if cursor.stage == GcStage::Mark {
        if let Some(mark) = cursor.mark.take() {
            if mark.frontier.is_empty() {
                Some(ClosureWalker::from_mark_cursor(&mark))
            } else {
                Some(ClosureWalker::from_mark_cursor(&mark))
            }
        } else {
            Some(ClosureWalker::new(&roots))
        }
    } else if let Some(mark) = cursor.mark.as_ref() {
        Some(ClosureWalker::from_mark_cursor(mark))
    } else {
        None
    };

    if cursor.stage == GcStage::Mark {
        let mut walking = walker.take().expect("a mark stage has a walker");
        loop {
            if let Some(trip) = walking.gate() {
                return gate_abort(&bucket, &mut budget, cursor, trip, 0, 0).await;
            }
            let Some(hash) = walking.next_read() else { break };
            if budget.spent_out(now_ms()) {
                cursor.mark = Some(walking.to_mark_cursor());
                return freeze(&bucket, &mut budget, &cursor).await;
            }
            match read_walk_narinfo(&bucket, &mut budget, &hash).await {
                WalkFetch::Document(document) => walking.answer(hash, Ok(document)),
                WalkFetch::Missing => walking.answer(hash, Err(WalkReadError::Absent)),
                WalkFetch::Corrupt => walking.answer(hash, Err(WalkReadError::Unparseable)),
                WalkFetch::Outage(failure) => {
                    // A storage outage is transient: park the run here,
                    // unanswered, and the next tick re-reads the same path.
                    log::event(
                        "error",
                        "gc.walk_read_failed",
                        &[("hash", hash.to_string()), ("error", failure.to_string())],
                    );
                    cursor.mark = Some(walking.to_mark_cursor());
                    return freeze(&bucket, &mut budget, &cursor).await;
                }
            }
        }
        let outcome = walking.into_outcome();
        if let Some(trip) = outcome.gate.clone() {
            return gate_abort(
                &bucket,
                &mut budget,
                cursor,
                trip,
                outcome.marked.len() as u64,
                outcome.unreadable_deep as u64,
            )
            .await;
        }
        // Marks complete: freeze them with an empty frontier so a later
        // tick skips the walk but keeps the marks for candidates.
        walker = Some(ClosureWalker::new(&roots));
        cursor.mark = None;
        cursor.stage = GcStage::Candidates;
        write_stage_artifact(
            &bucket,
            &mut budget,
            &cursor.run_id,
            "mark",
            &serde_json::json!({
                "markedPaths": outcome.marked.len(),
                "unreadableDeep": outcome.unreadable_deep,
                "finishedAtMs": now_ms(),
            }),
        )
        .await?;
        cursor_outcome_helper(&mut cursor, &outcome);
        if budget.spent_out(now_ms()) {
            cursor.mark = Some(mark_cursor_of_outcome(&roots, &outcome));
            return freeze(&bucket, &mut budget, &cursor).await;
        }
        cursor.mark = Some(mark_cursor_of_outcome(&roots, &outcome));
        walker = None;
    }

    Ok(())
}

/// The set the report keeps for marks.
fn cursor_outcome_helper(cursor: &mut GcCursor, outcome: &WalkOutcome) {
    cursor.inventory_paths = cursor.inventory_paths;
    let _ = outcome;
}

