/// value is operator-written.
pub(crate) fn admins(env: &Env) -> Vec<String> {
    env.var("CACHET_ADMINS")
        .ok()
        .map(|value| {
            value
                .to_string()
                .split(',')
                .map(|part| part.trim().to_string())
