//! The store snapshot's grammar and the diff between two of them. The
//! snapshot file is plain text: one store path per line, which is also
//! the shape the previous pipeline wrote, so old composite-run snapshots
//! still read.

use cachet_core::constants::PUSH_PATHS_MAX;

/// One store path per line, whitespace tolerant, empties dropped.
pub fn parse_snapshot(text: &str) -> Vec<String> {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(str::to_string)
        .collect()
}

/// The paths the job added: `after` minus `before`, preserving after
/// order and collapsing repeats. A missing `before` degrades to the whole
/// store, and [`bound_candidates`] is what keeps that honest.
pub fn store_diff(before: &str, after: &str) -> Vec<String> {
    let mut seen: std::collections::BTreeSet<String> =
        parse_snapshot(before).into_iter().collect();
    parse_snapshot(after)
        .into_iter()
        .filter(|path| seen.insert(path.clone()))
        .collect()
}

/// The candidate bound: past it the push refuses rather than uploading
/// the world on a misread snapshot.
///
/// # Errors
///
/// [`crate::PushError::TooManyCandidates`] past the cap.
pub fn bound_candidates(candidates: &[String]) -> Result<(), crate::PushError> {
    if candidates.len() as u64 > PUSH_PATHS_MAX {
        return Err(crate::PushError::TooManyCandidates(candidates.len()));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_grammar_is_lines_trimmed() {
        assert_eq!(
            parse_snapshot(" /nix/store/aaa-bash \n\n/nix/store/bbb-zsh\t\n"),
            vec![
                "/nix/store/aaa-bash".to_string(),
                "/nix/store/bbb-zsh".to_string(),
            ],
        );
        assert!(parse_snapshot("\n \n").is_empty());
    }

    #[test]
    fn the_diff_tracks_additions_in_order() {
        let before = "/nix/store/aaa-a\n/nix/store/bbb-b\n";
        let after = "/nix/store/bbb-b\n/nix/store/ccc-c\n/nix/store/ccc-c\n/nix/store/ddd-d\n";
        assert_eq!(
            store_diff(before, after),
            vec![
                "/nix/store/ccc-c".to_string(),
                "/nix/store/ddd-d".to_string(),
            ],
        );
        assert!(store_diff(before, before).is_empty());
    }

    #[test]
    fn the_bound_refuses_the_world() {
        let many: Vec<String> = (0..PUSH_PATHS_MAX + 1)
            .map(|i| format!("/nix/store/{i:032}-x"))
            .collect();
        assert!(matches!(
            bound_candidates(&many),
            Err(crate::PushError::TooManyCandidates(n)) if n as u64 == PUSH_PATHS_MAX + 1,
        ));
        let ok: Vec<String> = vec!["/nix/store/aaa-a".to_string()];
        assert!(bound_candidates(&ok).is_ok());
    }
}

//! The failure vocabulary: the push never fails the job, and its lines
//! carry the reason in full. Display text is the diagnostic contract
//! operators grep for.

use core::fmt;

use cachet_core::constants::PUSH_PATHS_MAX;

/// Everything that stops the push short. CI maps any of these to one
/// stderr line and a green job; the text stays close to the previous
/// implementation's wording because runbooks still quote it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PushError {
    /// A required input was missing, named for the operator.
    MissingConfig {
        /// The unset variables, in the documented order.
        missing: Vec<&'static str>,
    },
    /// A nix command failed.
    CommandFailed {
        /// The invocation as printed.
        argv: String,
        /// The failure text the command gave.
        message: String,
    },
    /// The diff outgrew the candidate cap.
    TooManyCandidates(usize),
    /// The OIDC request failed before it issued a token.
    OidcUnavailable(String),
    /// The OIDC response carried no token.
    OidcEmpty,
    /// An upload HTTP call failed its attempts.
    UploadFailed {
        /// The operation label: `PUT {key}`, `part N of {key}`, and so on.
        what: String,
        /// How many attempts ran.
        attempts: u32,
        /// The last failure text.
        last: String,
    },
    /// The object exceeded what the plan can ship.
    TooLarge {
        /// The staging-relative key.
        key: String,
    },
    /// A staging object had an implausible size.
    ImplausibleSize {
        /// The staging-relative key.
        key: String,
    },
    /// The staging directory could not be read.
    StagingUnreadable {
        /// The failure text.
        message: String,
    },
}

impl fmt::Display for PushError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingConfig { missing } => write!(
                f,
                "nothing pushed, because {} {} unset. The cachet-setup composite action exports \
                 these to the job environment; if you are running the post action directly, set \
                 them yourself.",
                missing.join(", "),
                if missing.len() == 1 { "is" } else { "are" },
            ),
            Self::CommandFailed { argv, message } => write!(f, "{argv} failed: {message}"),
            Self::TooManyCandidates(count) => {
                write!(f, "this job added {count} store paths, more than the {PUSH_PATHS_MAX} cap")
            }
            Self::OidcUnavailable(message) => write!(f, "{message}"),
            Self::OidcEmpty => write!(f, "the OIDC token response carried no token"),
            Self::UploadFailed {
                what,
                attempts,
                last,
            } => write!(f, "{what} failed after {attempts} attempts: {last}"),
            Self::TooLarge { key } => write!(f, "{key} is too large to upload"),
            Self::ImplausibleSize { key } => write!(f, "{key} has an implausible size"),
            Self::StagingUnreadable { message } => {
                write!(f, "could not read the staging directory: {message}")
            }
        }
    }
}

impl std::error::Error for PushError {}

//! The upload plan: staging-layout reading, request ordering, per-object
//! mechanics, and URL construction. Every decision here is pure data; the
//! pipeline executes what these functions answer.

use cachet_core::constants::UPLOAD_SINGLE_MAX_BYTES;
use cachet_core::multipart::plan_shape;

use crate::error::PushError;

/// One object as the staging directory reports it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StagedObject {
    /// The bucket key and request path: the staging-relative path.
    pub key: String,
    /// Its size in bytes.
    pub size_bytes: u64,
    /// The staging filename: the key minus any leading `nar/`.
    pub file_name: String,
}

impl StagedObject {
    /// Whether the object rides the narinfo ordering slot.
    pub fn is_narinfo(&self) -> bool {
        self.key.ends_with(cachet_core::constants::NARINFO_KEY_SUFFIX)
    }
}

/// Read a staging directory's layout the nix way: top-level `*.narinfo`
/// files, and the object files under `nar/`. Everything else is the
/// pipeline's own noise and fails the read.
///
/// # Errors
///
/// [`PushError::StagingUnreadable`] for an entry that fits neither shape.
pub fn read_staging_layout(entries: &[(String, u64)]) -> Result<Vec<StagedObject>, PushError> {
    let mut objects = Vec::with_capacity(entries.len());
    for (name, size_bytes) in entries {
        let key = if name.ends_with(cachet_core::constants::NARINFO_KEY_SUFFIX)
            && !name.contains('/')
        {
            name.clone()
        } else if let Some(rest) = name.strip_prefix("nar/") {
            if rest.contains('/') {
                return Err(PushError::StagingUnreadable {
                    message: format!("{name} nests deeper than nar/"),
                });
            }
            name.clone()
        } else {
            return Err(PushError::StagingUnreadable {
                message: format!("{name} fits neither the narinfo shape nor nar/"),
            });
        };
        objects.push(StagedObject {
            file_name: key
                .strip_prefix("nar/")
                .map_or_else(|| key.clone(), str::to_string),
            key,
            size_bytes: *size_bytes,
        });
    }
    Ok(objects)
}

/// The upload order: every NAR before every narinfo, stable inside each
/// kind, because the cache refuses a narinfo whose NAR is absent
/// (NEVER-DANGLE).
pub fn upload_order(objects: &mut [StagedObject]) {
    objects.sort_by_key(|object| object.is_narinfo());
}

/// One object's ride: the whole body in one PUT, or the multipart
/// quartet.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UploadMechanics {
    /// `PUT /{key}` with the whole body.
    Single,
    /// The multipart plan: part count from the shared part math.
    Multipart(cachet_core::multipart::PartPlan),
}

/// Decide the mechanics. Nix's stat answers the size; an implausible
/// answer fails before any byte moves. The single-PUT cap compares
/// inclusively: exactly-at-cap rides single, as the worker's guard
/// agrees. The multipart refusal delegates to the shared plan's own
/// reasoning.
///
/// # Errors
///
/// [`PushError::TooLarge`] past the parts cap;
/// [`PushError::ImplausibleSize`]!? — sizes come from stat so this branch
/// exists for completeness against adapters, expecting never to fire.
pub fn plan_mechanics(key: &str, size_bytes: u64) -> Result<UploadMechanics, PushError> {
    if size_bytes <= UPLOAD_SINGLE_MAX_BYTES {
        return Ok(UploadMechanics::Single);
    }
    plan_shape(size_bytes)
        .map(UploadMechanics::Multipart)
        .map_err(|_| PushError::TooLarge {
            key: key.to_string(),
        })
}

/// The request URL: trailing slashes stripped from the base once, the
/// key verbatim, the query appended. Project and upload ids are owned by
/// grammar-checked constructors upstream of here.
pub fn object_url(cache_url: &str, key: &str, query: &str) -> String {
    format!("{}/{key}{query}", cache_url.trim_end_matches('/'))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_layout_reads_the_two_shapes() {
        let entries = vec![
            ("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.narinfo".to_string(), 1_000_u64),
            ("nar/xxxx.nar.zst".to_string(), 2_000_u64),
        ];
        let objects = read_staging_layout(&entries).expect("the layout reads");
        assert_eq!(objects[0].key, "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.narinfo");
        assert_eq!(objects[1].key, "nar/xxxx.nar.zst");
        assert_eq!(objects[1].file_name, "xxxx.nar.zst");
        assert!(read_staging_layout(&[("README".to_string(), 1)]).is_err());
        assert!(read_staging_layout(&[("nar/deep/x".to_string(), 1)]).is_err());
    }

    #[test]
    fn narinfos_go_last_in_stable_order() {
        let mut objects = read_staging_layout(&[
            ("c".to_string() + ".narinfo", 1),
            ("nar/b.nar.zst".to_string(), 2),
            ("a".to_string() + ".narinfo", 1),
            ("nar/d.nar.zst".to_string(), 2),
        ])
        .expect("reads");
        upload_order(&mut objects);
        let keys: Vec<&str> = objects.iter().map(|o| o.key.as_str()).collect();
        assert_eq!(keys, vec!["nar/b.nar.zst", "nar/d.nar.zst", "c.narinfo", "a.narinfo"]);
    }

    #[test]
    fn the_cap_rides_single_and_past_it_goes_multipart() {
        assert_eq!(
            plan_mechanics("nar/x.nar", UPLOAD_SINGLE_MAX_BYTES).expect("at cap"),
            UploadMechanics::Single,
        );
        match plan_mechanics("nar/x.nar", UPLOAD_SINGLE_MAX_BYTES + 1).expect("past cap") {
            UploadMechanics::Multipart(plan) => {
                assert_eq!(plan.parts.len() as u64, (UPLOAD_SINGLE_MAX_BYTES + 1).div_ceil(cachet_core::constants::UPLOAD_PART_BYTES));
            }
            UploadMechanics::Single => panic!("past the cap must not ride single"),
        }
    }

    #[test]
    fn urls_strip_the_base_once() {
        assert_eq!(
            object_url("https://cachet.example.com/", "nar/x.nar.zst", ""),
            "https://cachet.example.com/nar/x.nar.zst",
        );
        assert_eq!(
            object_url("https://cachet.example.com//", "x.narinfo", "?uploads"),
            "https://cachet.example.com/x.narinfo?uploads",
        );
    }
}

