//! cachet-push is the writer-side pipeline as a native library (CLAUDE.md
//! §1): snapshot the local store, diff against a previous snapshot, filter
//! against the cache and the upstream substituter, stage through nix with
//! zstd compression, upload NARs before narinfos with a fresh OIDC token
//! per request, and renew the project lease on the default branch. The CI
//! contract is to log and exit zero on failure rather than fail the job.
//!
//! Drawn in two layers: the decision layer (`snapshot`, `plan`, `retry`,
//! `filter`) is pure data with unit proofs; the execution layer (`oidc`,
//! `http`, `pipeline`) composes decisions with nix and the wire.

#![forbid(unsafe_code)]

pub mod error;
pub mod plan;
pub mod snapshot;

pub use error::PushError;

//! The two presence filters, decided over probe answers as data: pass one
//! drops paths the upstream substituter already serves, pass two drops
//! paths cachet itself already holds. An answer a client cannot get is
//! `None`, and the path stays: a probe failure must never become a drop,
//! because rebuilding is the safe side of the error.

/// The pass-one tally, in candidate order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FilterTally {
    /// Paths this pass kept, roots first then survivors in candidate
    /// order, which is the order the lease writes them in.
    pub kept: Vec<String>,
    /// Paths the upstream probe answered present.
    pub upstream_hits: usize,
    /// Probes that produced no answer.
    pub probe_failures: usize,
}

/// The pass-two tally.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CacheTally {
    /// Paths to upload, in candidate order.
    pub to_upload: Vec<String>,
    /// Paths cachet itself already held.
    pub cache_hits: usize,
    /// Probes that produced no answer.
    pub probe_failures: usize,
}

/// Pass one: roots always keep (never probed); every other candidate
/// takes one upstream probe, with `Some(true)` dropping it and `None`
/// keeping it counted.
pub fn filter_against_upstream(
    candidates: &[String],
    root_paths: &std::collections::BTreeSet<String>,
    probe: &dyn Fn(&str) -> Option<bool>,
) -> FilterTally {
    let mut tally = FilterTally {
        kept: Vec::new(),
        upstream_hits: 0,
        probe_failures: 0,
    };
    for path in candidates {
        if root_paths.contains(path) {
            tally.kept.push(path.clone());
            continue;
        }
        match probe(path) {
            Some(true) => tally.upstream_hits += 1,
            Some(false) => tally.kept.push(path.clone()),
            None => {
                tally.probe_failures += 1;
                tally.kept.push(path.clone());
            }
        }
    }
    tally
}

/// Pass two: cachet's own HEAD answers `Some(true)` for held paths; every
/// survivor of pass one is probed, roots included.
pub fn drop_already_cached(
    candidates: &[String],
    probe: &dyn Fn(&str) -> Option<bool>,
) -> CacheTally {
    let mut tally = CacheTally {
        to_upload: Vec::new(),
        cache_hits: 0,
        probe_failures: 0,
    };
    for path in candidates {
        match probe(path) {
            Some(true) => tally.cache_hits += 1,
            Some(false) => tally.to_upload.push(path.clone()),
            None => {
                tally.probe_failures += 1;
                tally.to_upload.push(path.clone());
            }
        }
    }
    tally
}

#[cfg(test)]
mod tests {
    use super::*;

    fn paths(names: &[&str]) -> Vec<String> {
        names.iter().map(|n| n.to_string()).collect()
    }

    #[test]
    fn roots_skip_the_upstream_probe() {
        let roots: std::collections::BTreeSet<String> =
            paths(&["/nix/store/a"]).into_iter().collect();
        let tally = filter_against_upstream(&paths(&["/nix/store/a", "/nix/store/b"]), &roots, &|_| {
            panic!("a root must never be probed")
        });
        assert_eq!(tally.kept, paths(&["/nix/store/a"]));
    }

    #[test]
    fn presence_drops_absence_keeps_unknown_keeps_counted() {
        let tally = filter_against_upstream(
            &paths(&["/nix/store/hit", "/nix/store/miss", "/nix/store/unk"]),
            &std::collections::BTreeSet::new(),
            &|path| match path {
                "/nix/store/hit" => Some(true),
                "/nix/store/miss" => Some(false),
                _ => None,
            },
        );
        assert_eq!(tally.kept, paths(&["/nix/store/miss", "/nix/store/unk"]));
        assert_eq!(tally.upstream_hits, 1);
        assert_eq!(tally.probe_failures, 1);
    }

    #[test]
    fn the_cache_pass_has_no_roots_exception() {
        let tally = drop_already_cached(&paths(&["/nix/store/x", "/nix/store/y"]), &|path| {
            (path == "/nix/store/x").then_some(true)
        });
        assert_eq!(tally.to_upload, paths(&["/nix/store/y"]));
        assert_eq!(tally.cache_hits, 1);
    }
}

//! The retry policy as pure shape: counts, delays, and the failure line.
//! Retries are the whole mitigation against a flaky connection, and the
//! envelope is small enough to review as data.

/// Total attempts per operation.
pub const RETRY_MAX: u32 = 3;
/// The base of the linear backoff, in milliseconds.
pub const RETRY_BASE_DELAY_MS: u64 = 500;

/// The sleep after attempt `tries` (zero-based) fails: base times
/// `tries + 1`. There is no sleep after the final attempt — its failure
/// returns instead.
pub fn attempt_delay_ms(tries: u32) -> u64 {
    RETRY_BASE_DELAY_MS * u64::from(tries + 1)
}

/// Sleep decisions: how long after a failed attempt, if it is not the
/// last.
pub fn delay_after(tries: u32) -> Option<u64> {
    (tries + 1 < RETRY_MAX).then(|| attempt_delay_ms(tries))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_envelope_is_500_then_1000_then_done() {
        assert_eq!(delay_after(0), Some(500));
        assert_eq!(delay_after(1), Some(1_000));
        assert_eq!(delay_after(2), None);
    }
}

//! The seams the pipeline composes over: nix commands, file reads, HTTP,
//! and the OIDC mint. Each trait is small and synchronous-shaped; the
//! real implementations live in `real`, the scripted ones in the tests,
//! and the pipeline never knows which.

use std::path::{Path, PathBuf};

use crate::PushError;

/// What the pipeline needs from nix and the filesystem.
pub trait Commands: Send + Sync {
    /// `nix path-info --all`, raw stdout.
    fn path_info_all(&self) -> impl Future<Output = Result<String, PushError>> + Send;
    /// `nix path-info <installable>`, raw stdout.
    fn path_info(&self, installable: &str) -> impl Future<Output = Result<String, PushError>> + Send;
    /// `nix copy --to <destination> <paths...>`.
    fn copy_to(
        &self,
        destination: &str,
        paths: &[String],
    ) -> impl Future<Output = Result<(), PushError>> + Send;
    /// One directory level of (name, size), for the staging layout.
    fn read_dir(&self, dir: &Path) -> impl Future<Output = Result<Vec<(String, u64)>, PushError>> + Send;
    /// A file's bytes, for single-PUT bodies.
    fn read_file(&self, path: &Path) -> impl Future<Output = Result<Vec<u8>, PushError>> + Send;
    /// A file's byte range, for multipart parts.
    fn read_range(
        &self,
        path: &Path,
        offset: u64,
        len: u64,
    ) -> impl Future<Output = Result<Vec<u8>, PushError>> + Send;
}

/// One HTTP answer: status and body. Headers arrive through the request
/// parameters rather than a type map, because the pipeline's shapes are
/// exact and few.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WireAnswer {
    /// The status code.
    pub status: u16,
    /// The body bytes.
    pub body: Vec<u8>,
}

/// What the pipeline needs from the wire.
pub trait Http: Send + Sync {
    /// `HEAD <url>`, optionally Bearer-authorized.
    fn head(&self, url: &str, bearer: Option<&str>) -> impl Future<Output = Result<u16, PushError>> + Send;
    /// `GET <url>`, optionally Bearer-authorized.
    fn get(&self, url: &str, bearer: Option<&str>) -> impl Future<Output = Result<WireAnswer, PushError>> + Send;
    /// `PUT <url>` with an exact body and headers.
    fn put(
        &self,
        url: &str,
        bearer: &str,
        body: Vec<u8>,
        headers: &[(String, String)],
    ) -> impl Future<Output = Result<WireAnswer, PushError>> + Send;
    /// `POST <url>` with an exact body and headers.
    fn post(
        &self,
        url: &str,
        bearer: &str,
        body: Vec<u8>,
        headers: &[(String, String)],
    ) -> impl Future<Output = Result<WireAnswer, PushError>> + Send;
    /// `DELETE <url>`, Bearer-authorized.
    fn delete(&self, url: &str, bearer: &str) -> impl Future<Output = Result<u16, PushError>> + Send;
}

/// The OIDC mint, isolated the way the pipeline sees it: one call, one
/// fresh token (or the error line).
pub trait TokenSource: Send + Sync {
    /// Mint a fresh OIDC token for the audience.
    fn mint(&self, audience: &str) -> impl Future<Output = Result<String, PushError>> + Send;
}

/// Where the snapshot file lives between a run's steps.
pub fn snapshot_path(runner_temp: &Path) -> PathBuf {
    runner_temp.join("cachet-store-before.txt")
}

//! The OIDC mint: GitHub answers one request with one JsonWebToken. The
//! pipeline refreshes by minting again inside every attempt, so a 401 is
//! retried with a seconds-old credential rather than a refresh dance.

use crate::adapters::{Http, TokenSource};
use crate::error::PushError;

/// The two environment variables the mint answers to. Their absence is a
/// configuration fact with its own sentence, because the fix lives in the
/// job's YAML, not here.
pub struct OidcEnv {
    /// `ACTIONS_ID_TOKEN_REQUEST_URL`, verbatim.
    pub request_url: String,
    /// `ACTIONS_ID_TOKEN_REQUEST_TOKEN`, verbatim.
    pub request_token: String,
}

/// Read the mint's environment from explicit pairs, so tests never touch
/// ambient state.
///
/// # Errors
///
/// [`PushError::OidcUnavailable`] naming the YAML fix.
pub fn oidc_env(vars: &[(String, String)]) -> Result<OidcEnv, PushError> {
    let find = |name: &str| vars.iter().find(|(key, _)| key == name).map(|(_, v)| v.clone());
    let url = find("ACTIONS_ID_TOKEN_REQUEST_URL");
    let token = find("ACTIONS_ID_TOKEN_REQUEST_TOKEN");
    match (url, token) {
        (Some(request_url), Some(request_token)) if !request_url.is_empty() && !request_token.is_empty() => {
            Ok(OidcEnv {
                request_url,
                request_token,
            })
        }
        _ => Err(PushError::OidcUnavailable(
            "no OIDC token request variables. Add `permissions: { id-token: write }` to the job.".to_string(),
        )),
    }
}

/// RFC 3986 unreserved pass-through for the audience parameter.
fn encode_component(value: &str) -> String {
    const UNRESERVED: &[u8] = b"REDACTED._~";
    let mut out = String::with_capacity(value.len());
    for byte in value.as_bytes() {
        if UNRESERVED.contains(byte) {
            out.push(char::from(*byte));
        } else {
            out.push_str(&format!("%{byte:02X}"));
        }
    }
    out
}

/// The mint over a generic wire. GitHub's request URL already carries its
/// query; the audience appends as another `&` parameter, verbatim with
/// the previous implementation.
pub struct OidcTokens<'a, H> {
    env: &'a OidcEnv,
    http: &'a H,
}

impl<'a, H: Http> OidcTokens<'a, H> {
    /// Borrow pieces.
    pub fn new(env: &'a OidcEnv, http: &'a H) -> Self {
        Self { env, http }
    }
}

#[derive(Debug, serde::Deserialize)]
struct MintAnswer {
    value: Option<String>,
}

impl<H: Http> TokenSource for OidcTokens<'_, H> {
    async fn mint(&self, audience: &str) -> Result<String, PushError> {
        let url = format!(
            "{}&audience={}",
            self.env.request_url,
            encode_component(audience),
        );
        let answer = self
            .http
            .get(&url, Some(&self.env.request_token))
            .await
            .map_err(|failure| {
                PushError::OidcUnavailable(format!("the OIDC token request failed: {failure}"))
            })?;
        if !(200..300).contains(&answer.status) {
            return Err(PushError::OidcUnavailable(format!(
                "the OIDC token request returned {}",
                answer.status,
            )));
        }
        let parsed: MintAnswer = serde_json::from_slice(&answer.body)
            .map_err(|failure| PushError::OidcUnavailable(format!("the OIDC token answer did not parse: {failure}")))?;
        parsed
            .value
            .filter(|token| !token.is_empty())
            .ok_or(PushError::OidcEmpty)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn missing_variables_name_the_yaml_fix() {
        match oidc_env(&[]) {
            Err(PushError::OidcUnavailable(message)) => {
                assert!(message.contains("id-token: write"), "{message}");
            }
            other => panic!("expected the config error, got {other:?}"),
        }
        assert!(oidc_env(&[(
            "ACTIONS_ID_TOKEN_REQUEST_URL".to_string(),
            "https://x".to_string(),
        )])
        .is_err());
    }

    #[test]
    fn the_audience_encodes_minimally() {
        assert_eq!(encode_component("cachet"), "cachet");
        assert_eq!(encode_component("api:GitHub Actions"), "api%3AGitHub%20Actions");
    }
}

//! The pipeline itself: `main_snapshot` for the composite's first step,
//! `push` for the post step. Sequencing, retries, and request shapes
//! compose the decision layer over the adapters; nothing here knows nix
//! argv or reqwest.

use futures_util::StreamExt as _;

use crate::adapters::{Commands, Http, TokenSource, WireAnswer};
use crate::error::PushError;
use crate::filter::{drop_already_cached, filter_against_upstream};
use crate::plan::{
    StagedObject, UploadMechanics, object_url, plan_mechanics, read_staging_layout, upload_order,
};
use crate::retry::{RETRY_MAX, delay_after};
use crate::snapshot::{bound_candidates, parse_snapshot, store_diff};

/// The values the composite resolves once into the job environment.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PushInputs {
    /// The cache's base URL.
    pub cache_url: String,
    /// The OIDC audience.
    pub audience: String,
    /// The lease name: `owner-repo` hyphenated.
    pub project: String,
    /// The flake installables whose closures root this push.
    pub installables: Vec<String>,
    /// The upstream substituter to filter against.
    pub upstream_url: String,
    /// Whether this run answers for the configured default branch.
    pub is_default_branch: bool,
}

/// What the push did, for the caller's log lines.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct PushOutcome {
    /// Candidates from the diff.
    pub added_paths: usize,
    /// Paths kept because the roots named them.
    pub roots_kept: usize,
    /// Paths the upstream already serves.
    pub upstream_hits: usize,
    /// Paths cachet already held.
    pub cache_hits: usize,
    /// Probes that answered nothing.
    pub probe_failures: usize,
    /// Objects (NAR plus narinfo files) uploaded.
    pub uploaded_objects: usize,
    /// Whether the lease renewed on this run.
    pub lease_renewed: bool,
}

/// Progress the caller renders. Each variant names one past-tense fact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PushEvent {
    /// The before-snapshot wrote.
    SnapshotTaken,
    /// The before-snapshot could not be taken; the push declines.
    MainSnapshotFailed {
        /// The command's complaint.
        message: String,
    },
    /// The job added nothing to the store.
    NothingAdded,
    /// One installable would not resolve and rides the lease unnamed.
    InstallableUnresolved {
        /// The installable as given.
        installable: String,
    },
    /// Pass one's tally.
    UpstreamTally {
        /// Paths still bound for pushing.
        to_push: usize,
        /// Paths the upstream already serves.
        upstream_hits: usize,
        /// Probes with no answer.
        probe_failures: usize,
    },
    /// Pass two's tally.
    CacheTally {
        /// Paths still bound for upload.
        to_upload: usize,
        /// Paths cachet already held.
        cache_hits: usize,
        /// Probes with no answer.
        probe_failures: usize,
    },
    /// All surviving objects landed.
    UploadedObjects {
        /// Narinfo plus NAR file count.
        count: usize,
    },
    /// The renewal's branch gate refused.
    LeaseSkippedNotDefaultBranch,
    /// The lease renewed.
    LeaseRenewed {
        /// The project it covers.
        project: String,
    },
}

/// The composite's main step: snapshot, or decline gracefully. A command
/// failure answers `None` with its event — the job must finish green.
pub async fn main_snapshot<C: Commands>(
    commands: &C,
    events: &mut dyn FnMut(PushEvent),
) -> Result<Option<String>, PushError> {
    match commands.path_info_all().await {
        Ok(text) => {
            events(PushEvent::SnapshotTaken);
            Ok(Some(text))
        }
        Err(failure) => {
            events(PushEvent::MainSnapshotFailed {
                message: failure.to_string(),
            });
            Ok(None)
        }
    }
}

/// The post step: diff, filter, stage, upload, renew. The pipeline's
/// result IS the job's diagnosis; the caller decides what green means.
pub async fn push<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    before_snapshot: &str,
    staging_dir: &std::path::Path,
    events: &mut dyn FnMut(PushEvent),
) -> Result<PushOutcome, PushError> {
    let mut outcome = PushOutcome::default();

    let after = commands.path_info_all().await?;
    let candidates = store_diff(before_snapshot, &after);
    bound_candidates(&candidates)?;
    outcome.added_paths = candidates.len();
    if candidates.is_empty() {
        events(PushEvent::NothingAdded);
        return Ok(outcome);
    }

    // Roots resolve best-effort: an unresolvable installable still rides
    // the lease by name; only its paths are missing.
    let mut resolved_root_paths: Vec<String> = Vec::new();
    for installable in &inputs.installables {
        match commands.path_info(installable).await {
            Ok(text) => resolved_root_paths.extend(parse_snapshot(&text)),
            Err(_) => events(PushEvent::InstallableUnresolved {
                installable: installable.clone(),
            }),
        }
    }
    let root_set: std::collections::BTreeSet<String> = resolved_root_paths.iter().cloned().collect();
    outcome.roots_kept = candidates
        .iter()
        .filter(|path| root_set.contains(*path))
        .count();

    // Pass one: upstream. Probes fan out sixteen wide, ordered answers.
    let probeables: Vec<String> = candidates
        .iter()
        .filter(|path| !root_set.contains(*path))
        .cloned()
        .collect();
    let probe_token = tokens.mint(&inputs.audience).await?;
    let upstream_answers = probe_pool(http, &inputs.upstream_url, None, &probeables).await;
    let upstream = filter_against_upstream(&candidates, &root_set, &|path| {
        upstream_answers
            .iter()
            .find(|(candidate, _)| candidate == path)
            .and_then(|(_, answer)| *answer)
    });
    outcome.upstream_hits = upstream.upstream_hits;
    events(PushEvent::UpstreamTally {
        to_push: upstream.kept.len(),
        upstream_hits: upstream.upstream_hits,
        probe_failures: upstream.probe_failures,
    });
    outcome.probe_failures += upstream.probe_failures;
    if upstream.kept.is_empty() {
        return finish_with_lease(commands, http, tokens, sleep, inputs, events, outcome, &resolved_root_paths, 0).await;
    }

    // Pass two: cachet itself.
    let cache_answers = probe_pool(http, &inputs.cache_url, Some(&probe_token), &upstream.kept).await;
    let cached = drop_already_cached(&upstream.kept, &|path| {
        cache_answers
            .iter()
            .find(|(candidate, _)| candidate == path)
            .and_then(|(_, answer)| *answer)
    });
    outcome.cache_hits = cached.cache_hits;
    events(PushEvent::CacheTally {
        to_upload: cached.to_upload.len(),
        cache_hits: cached.cache_hits,
        probe_failures: cached.probe_failures,
    });
    outcome.probe_failures += cached.probe_failures;
    if cached.to_upload.is_empty() {
        return finish_with_lease(commands, http, tokens, sleep, inputs, events, outcome, &resolved_root_paths, 0).await;
    }

    // Stage through nix: the store's own serialization, zstd, no signing
    // — the cache's pipeline signs after it verifies.
    let destination = format!("file://{}?compression=zstd", staging_dir.display());
    commands.copy_to(&destination, &cached.to_upload).await?;
    let entries = commands.read_dir(staging_dir).await?;
    let mut objects = read_staging_layout(&entries)?;
    upload_order(&mut objects);
    let uploaded = upload_objects(commands, http, tokens, sleep, inputs, &objects).await?;
    outcome.uploaded_objects = uploaded;
    events(PushEvent::UploadedObjects { count: uploaded });

    finish_with_lease(commands, http, tokens, sleep, inputs, events, outcome, &resolved_root_paths, uploaded).await
}

/// The renewal tail every non-empty candidate set reaches: gated on the
/// default branch, retried like everything else.
async fn finish_with_lease<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    events: &mut dyn FnMut(PushEvent),
    mut outcome: PushOutcome,
    resolved_root_paths: &[String],
    _uploaded: usize,
) -> Result<PushOutcome, PushError> {
    commands.path_info_all().await.map(|_| ())?; // placeholder no-op to keep generic C used
    if !inputs.is_default_branch {
        events(PushEvent::LeaseSkippedNotDefaultBranch);
        outcome.lease_renewed = false;
        return Ok(outcome);
    }
    let body = cachet_api::RenewalBody {
        installables: inputs.installables.clone(),
        store_paths: resolved_root_paths.to_vec(),
    };
    let body_bytes = serde_json::to_vec(&body).expect("the renewal body serializes");
    let url = object_url(&inputs.cache_url, &format!("roots/{}", inputs.project), "");
    with_retries(&format!("renew the lease for {}", inputs.project), sleep, || {
        let body_bytes = body_bytes.clone();
        let url = url.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .post(&url, &token, body_bytes, &[("content-type".to_string(), "application/json".to_string())])
                .await?;
            require_2xx(&format!("renew the lease for {}", inputs.project), answer)
        }
    })
    .await?;
    events(PushEvent::LeaseRenewed {
        project: inputs.project.clone(),
    });
    outcome.lease_renewed = true;
    Ok(outcome)
}

/// The probe pool: ordered answers, sixteen in flight, each one
/// `Some(present)` / `Some(absent)` / `None` for a request that could not
/// answer.
async fn probe_pool<H: Http>(
    http: &H,
    base_url: &str,
    bearer: Option<&str>,
    paths: &[String],
) -> Vec<(String, Option<bool>)> {
    futures_util::stream::iter(paths.iter().map(|path| {
        let bearer = bearer.map(str::to_string);
        async move {
            let url = probe_url(base_url, path);
            let answer = match http.head(&url, bearer.as_deref()).await {
                Ok(404) => Some(false),
                Ok(status) if (200..300).contains(&status) => Some(true),
                _ => None,
            };
            (path.clone(), answer)
        }
    }))
    .buffered(crates_io_concurrency())
    .collect()
    .await
}

/// The probe URL for one path: its hash half names the narinfo.
fn probe_url(base_url: &str, path: &str) -> String {
    let hash = cachet_core::keys::parse_store_path(path)
        .map(|parts| parts.hash.as_str().to_string())
        .unwrap_or_default();
    object_url(base_url, &format!("{hash}.narinfo"), "")
}

/// The probe pool's width: the constant the previous pipeline used.
const fn crates_io_concurrency() -> usize {
    16
}

/// Upload every object in order.
async fn upload_objects<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    objects: &[StagedObject],
) -> Result<usize, PushError> {
    let mut uploaded = 0;
    for object in objects {
        match plan_mechanics(&object.key, object.size_bytes)? {
            UploadMechanics::Single => {
                upload_single(commands, http, tokens, sleep, inputs, object).await?;
            }
            UploadMechanics::Multipart(shape) => {
                upload_multipart(commands, http, tokens, sleep, inputs, object, &shape).await?;
            }
        }
        uploaded += 1;
    }
    Ok(uploaded)
}

/// The single PUT, retried as a unit.
async fn upload_single<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    object: &StagedObject,
) -> Result<(), PushError> {
    let body = commands
        .read_file(&std::path::PathBuf::from("STAGING_PATCH_MARKER"))
        .await?;
    let _ = body;
    let url = object_url(&inputs.cache_url, &object.key, "");
    with_retries(&format!("PUT {}", object.key), sleep, || {
        let url = url.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .put(&url, &token, body.clone(), &[])
                .await?;
            require_2xx(&format!("PUT {}", object.key), answer)
        }
    })
    .await
}

/// The multipart quartet, each piece retried alone; a part that dies
/// aborts the upload best-effort.
async fn upload_multipart<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    object: &StagedObject,
    shape: &cachet_core::multipart::PlanShape,
) -> Result<(), PushError> {
    let url = object_url(&inputs.cache_url, &object.key, "?uploads");
    let created: cachet_api::UploadCreated = with_retries(&format!("begin {}", object.key), sleep, || {
        let url = url.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .post(
                    &url,
                    &token,
                    Vec::new(),
                    &[(
                        "x-cachet-upload-bytes".to_string(),
                        object.size_bytes.to_string(),
                    )],
                )
                .await?;
            let answer = require_2xx(&format!("begin {}", object.key), answer)?;
            serde_json::from_slice(&answer.body).map_err(|failure| PushError::UploadFailed {
                what: format!("begin {}", object.key),
                attempts: 1,
                last: format!("the begin answer did not parse: {failure}"),
            })
        }
    })
    .await?;

    let mut parts: Vec<crate::wire::CompletedPartWire> = Vec::new();
    for number in 1..=shape.count {
        let result = upload_one_part(commands, http, tokens, sleep, inputs, object, &created.upload_id, shape, number).await;
        if let Err(failure) = result {
            abort_multipart(http, tokens, inputs, object, &created.upload_id).await;
            return Err(failure);
        }
        match result {
            Ok(part) => parts.push(part),
            Err(unreachable) => return Err(unreachable),
        }
    }

    let url = object_url(&inputs.cache_url, &object.key, &format!("?uploadId={}", created.upload_id));
    let body = serde_json::to_vec(&parts).expect("the completion body serializes");
    with_retries(&format!("complete {}", object.key), sleep, || {
        let url = url.clone();
        let body = body.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .post(&url, &token, body, &[("content-type".to_string(), "application/json".to_string())])
                .await?;
            require_2xx(&format!("complete {}", object.key), answer)
        }
    })
    .await?;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn upload_one_part<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    inputs: &PushInputs,
    object: &StagedObject,
    upload_id: &str,
    shape: &cachet_core::multipart::PlanShape,
    number: u64,
) -> Result<crate::wire::CompletedPartWire, PushError> {
    let offset = (number - 1) * cachet_core::constants::UPLOAD_PART_BYTES;
    let length = if number == shape.count {
        shape.last_len
    } else {
        cachet_core::constants::UPLOAD_PART_BYTES
    };
    let body = commands
        .read_range(
            &std::path::PathBuf::from("STAGING_PATCH_MARKER"),
            offset,
            length,
        )
        .await?;
    let url = object_url(
        &inputs.cache_url,
        &object.key,
        &format!("?uploadId={upload_id}&partNumber={number}"),
    );
    let what = format!("part {number} of {}", object.key);
    with_retries(&what, sleep, || {
        let url = url.clone();
        let body = body.clone();
        let what = what.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http.put(&url, &token, body, &[]).await?;
            let answer = require_2xx(&what, answer)?;
            serde_json::from_slice(&answer.body).map_err(|failure| PushError::UploadFailed {
                what: what.clone(),
                attempts: 1,
                last: format!("the part answer did not parse: {failure}"),
            })
        }
    })
    .await
}

/// The abort: best-effort by contract; a mint failure skips silently and
/// the collector reclaims the upload later.
async fn abort_multipart<H: Http, T: TokenSource>(
    http: &H,
    tokens: &T,
    inputs: &PushInputs,
    object: &StagedObject,
    upload_id: &str,
) {
    let Ok(token) = tokens.mint(&inputs.audience).await else {
        return;
    };
    let url = object_url(&inputs.cache_url, &object.key, &format!("?uploadId={upload_id}"));
    let _ = http.delete(&url, &token).await;
}

/// The retry envelope: an operation runs until it works or the envelope
/// closes, with the failure line naming the label, the count, and the
/// last complaint.
async fn with_retries<T, Fut>(
    what: &str,
    sleep: &(dyn Fn(u64) -> futures_util::future::BoxFuture<'_, ()> + Sync),
    mut attempt: impl FnMut() -> Fut,
) -> Result<T, PushError>
where
    Fut: std::future::Future<Output = Result<T, PushError>>,
{
    let mut last = String::new();
    for tries in 0..RETRY_MAX {
        match attempt().await {
            Ok(value) => return Ok(value),
            Err(failure) => {
                last = failure.to_string();
                if let Some(delay_ms) = delay_after(tries) {
                    sleep(delay_ms).await;
                }
            }
        }
    }
    Err(PushError::UploadFailed {
        what: what.to_string(),
        attempts: RETRY_MAX,
        last,
    })
}

/// Any 2xx passes as the wire's ok; everything else fails with the body.
fn require_2xx(what: &str, answer: WireAnswer) -> Result<WireAnswer, PushError> {
    if (200..300).contains(&answer.status) {
        return Ok(answer);
    }
    Err(PushError::UploadFailed {
        what: what.to_string(),
        attempts: 1,
        last: format!(
            "{} {}",
            answer.status,
            String::from_utf8_lossy(&answer.body),
        ),
    })
}

//! The pipeline itself: `main_snapshot` for the composite's first step,
//! `push` for the post step. Sequencing, retries, and request shapes
//! compose the decision layer over the adapters; nothing here knows nix
//! argv or reqwest.

use futures_util::StreamExt as _;

use crate::adapters::{Commands, Http, TokenSource, WireAnswer};
use crate::error::PushError;
use crate::filter::{drop_already_cached, filter_against_upstream};
use crate::plan::{
    StagedObject, UploadMechanics, object_url, plan_mechanics, read_staging_layout, upload_order,
};
use crate::retry::{RETRY_MAX, delay_after};
use crate::snapshot::{bound_candidates, parse_snapshot, store_diff};

/// The probe pool's width: bounded fan-out for presence checks, matching
/// the previous pipeline's tuning.
const PROBE_CONCURRENCY: usize = 16;

/// The values the composite resolves once into the job environment.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PushInputs {
    /// The cache's base URL.
    pub cache_url: String,
    /// The OIDC audience.
    pub audience: String,
    /// The lease name: `owner-repo` hyphenated.
    pub project: String,
    /// The flake installables whose closures root this push.
    pub installables: Vec<String>,
    /// The upstream substituter to filter against.
    pub upstream_url: String,
    /// Whether this run answers for the configured default branch.
    pub is_default_branch: bool,
}

/// What the push did, for the caller's log lines.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct PushOutcome {
    /// Candidates from the diff.
    pub added_paths: usize,
    /// Paths kept because the roots named them.
    pub roots_kept: usize,
    /// Paths the upstream already serves.
    pub upstream_hits: usize,
    /// Paths cachet already held.
    pub cache_hits: usize,
    /// Probes that answered nothing.
    pub probe_failures: usize,
    /// Objects (NAR plus narinfo files) uploaded.
    pub uploaded_objects: usize,
    /// Whether the lease renewed on this run.
    pub lease_renewed: bool,
}

/// Progress the caller renders. Each variant names one past-tense fact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PushEvent {
    /// The before-snapshot wrote.
    SnapshotTaken,
    /// The before-snapshot could not be taken; the push declines.
    MainSnapshotFailed {
        /// The command's complaint.
        message: String,
    },
    /// The job added nothing to the store.
    NothingAdded,
    /// One installable would not resolve and rides the lease unnamed.
    InstallableUnresolved {
        /// The installable as given.
        installable: String,
    },
    /// Pass one's tally.
    UpstreamTally {
        /// Paths still bound for pushing.
        to_push: usize,
        /// Paths the upstream already serves.
        upstream_hits: usize,
        /// Probes with no answer.
        probe_failures: usize,
    },
    /// Pass two's tally.
    CacheTally {
        /// Paths still bound for upload.
        to_upload: usize,
        /// Paths cachet already held.
        cache_hits: usize,
        /// Probes with no answer.
        probe_failures: usize,
    },
    /// All surviving objects landed.
    UploadedObjects {
        /// Narinfo plus NAR file count.
        count: usize,
    },
    /// The renewal's branch gate refused.
    LeaseSkippedNotDefaultBranch,
    /// The lease renewed.
    LeaseRenewed {
        /// The project it covers.
        project: String,
    },
}

/// One sleep, injected so the unit lane never waits.
pub type Sleeper = dyn Fn(u64) -> futures_util::future::BoxFuture<'static, ()> + Send + Sync;

/// The composite's main step: snapshot, or decline gracefully. A command
/// failure answers `None` with its event — the job must finish green.
pub async fn main_snapshot<C: Commands>(
    commands: &C,
    events: &mut dyn FnMut(PushEvent),
) -> Result<Option<String>, PushError> {
    match commands.path_info_all().await {
        Ok(text) => {
            events(PushEvent::SnapshotTaken);
            Ok(Some(text))
        }
        Err(failure) => {
            events(PushEvent::MainSnapshotFailed {
                message: failure.to_string(),
            });
            Ok(None)
        }
    }
}

/// The post step: diff, filter, stage, upload, renew. The pipeline's
/// result IS the job's diagnosis; the caller decides what green means.
pub async fn push<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    before_snapshot: &str,
    staging_dir: &std::path::Path,
    events: &mut dyn FnMut(PushEvent),
) -> Result<PushOutcome, PushError> {
    let mut outcome = PushOutcome::default();

    let after = commands.path_info_all().await?;
    let candidates = store_diff(before_snapshot, &after);
    bound_candidates(&candidates)?;
    outcome.added_paths = candidates.len();
    if candidates.is_empty() {
        events(PushEvent::NothingAdded);
        return Ok(outcome);
    }

    // Roots resolve best-effort: an unresolvable installable still rides
    // the lease by name; only its paths are missing.
    let mut resolved_root_paths: Vec<String> = Vec::new();
    for installable in &inputs.installables {
        match commands.path_info(installable).await {
            Ok(text) => resolved_root_paths.extend(parse_snapshot(&text)),
            Err(_) => events(PushEvent::InstallableUnresolved {
                installable: installable.clone(),
            }),
        }
    }
    let root_set: std::collections::BTreeSet<String> =
        resolved_root_paths.iter().cloned().collect();
    outcome.roots_kept = candidates
        .iter()
        .filter(|path| root_set.contains(*path))
        .count();

    // Pass one: upstream. Probes fan out sixteen wide, answers ordered.
    let probe_token = tokens.mint(&inputs.audience).await?;
    let upstream_answers = probe_pool(http, &inputs.upstream_url, None, &candidates).await;
    let upstream = filter_against_upstream(&candidates, &root_set, &|path| {
        upstream_answers
            .iter()
            .find(|(candidate, _)| candidate == path)
            .and_then(|(_, answer)| *answer)
    });
    outcome.upstream_hits = upstream.upstream_hits;
    outcome.probe_failures += upstream.probe_failures;
    events(PushEvent::UpstreamTally {
        to_push: upstream.kept.len(),
        upstream_hits: upstream.upstream_hits,
        probe_failures: upstream.probe_failures,
    });
    if upstream.kept.is_empty() {
        return finish_with_lease(http, tokens, sleep, inputs, events, outcome, &resolved_root_paths)
            .await;
    }

    // Pass two: cachet itself.
    let cache_answers = probe_pool(http, &inputs.cache_url, Some(&probe_token), &upstream.kept).await;
    let cached = drop_already_cached(&upstream.kept, &|path| {
        cache_answers
            .iter()
            .find(|(candidate, _)| candidate == path)
            .and_then(|(_, answer)| *answer)
    });
    outcome.cache_hits = cached.cache_hits;
    outcome.probe_failures += cached.probe_failures;
    events(PushEvent::CacheTally {
        to_upload: cached.to_upload.len(),
        cache_hits: cached.cache_hits,
        probe_failures: cached.probe_failures,
    });
    if cached.to_upload.is_empty() {
        return finish_with_lease(http, tokens, sleep, inputs, events, outcome, &resolved_root_paths)
            .await;
    }

    // Stage through nix: the store's own serialization and compression,
    // unsigned — the cache's pipeline verifies, then signs.
    let destination = format!("file://{}?compression=zstd", staging_dir.display());
    commands.copy_to(&destination, &cached.to_upload).await?;
    let entries = commands.read_dir(staging_dir).await?;
    let mut objects = read_staging_layout(&entries)?;
    upload_order(&mut objects);
    let uploaded = upload_objects(commands, http, tokens, sleep, inputs, staging_dir, &objects).await?;
    outcome.uploaded_objects = uploaded;
    events(PushEvent::UploadedObjects { count: uploaded });

    finish_with_lease(http, tokens, sleep, inputs, events, outcome, &resolved_root_paths).await
}

/// The renewal tail every non-empty candidate set reaches: gated on the
/// default branch, retried in the envelope like everything else.
async fn finish_with_lease<H: Http, T: TokenSource>(
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    events: &mut dyn FnMut(PushEvent),
    mut outcome: PushOutcome,
    resolved_root_paths: &[String],
) -> Result<PushOutcome, PushError> {
    if !inputs.is_default_branch {
        events(PushEvent::LeaseSkippedNotDefaultBranch);
        outcome.lease_renewed = false;
        return Ok(outcome);
    }
    let body = cachet_api::RenewalBody {
        installables: inputs.installables.clone(),
        store_paths: resolved_root_paths.to_vec(),
    };
    let body_bytes = serde_json::to_vec(&body).expect("the renewal body serializes");
    let url = object_url(&inputs.cache_url, &format!("roots/{}", inputs.project), "");
    let what = format!("renew the lease for {}", inputs.project);
    with_retries(&what, sleep, || {
        let body_bytes = body_bytes.clone();
        let url = url.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .post(
                    &url,
                    &token,
                    body_bytes,
                    &[("content-type".to_string(), "application/json".to_string())],
                )
                .await?;
            require_2xx(&what, answer)
        }
    })
    .await?;
    events(PushEvent::LeaseRenewed {
        project: inputs.project.clone(),
    });
    outcome.lease_renewed = true;
    Ok(outcome)
}

/// The probe pool: ordered answers, sixteen in flight, each one
/// `Some(present)` / `Some(absent)` / `None` for a request that could not
/// answer.
async fn probe_pool<H: Http>(
    http: &H,
    base_url: &str,
    bearer: Option<&str>,
    paths: &[String],
) -> Vec<(String, Option<bool>)> {
    futures_util::stream::iter(paths.iter().map(|path| {
        let bearer = bearer.map(str::to_string);
        async move {
            let url = probe_url(base_url, path);
            let answer = match http.head(&url, bearer.as_deref()).await {
                Ok(404) => Some(false),
                Ok(status) if (200..300).contains(&status) => Some(true),
                _ => None,
            };
            (path.clone(), answer)
        }
    }))
    .buffered(PROBE_CONCURRENCY)
    .collect()
    .await
}

/// The probe URL for one path: its hash half names the narinfo. A path
/// outside the grammar is unprobeable: its probe answers nothing, and the
/// filter keeps it, fail-toward-rebuild.
fn probe_url(base_url: &str, path: &str) -> String {
    let hash = cachet_core::keys::parse_store_path(path)
        .map(|parts| parts.hash.as_str().to_string())
        .unwrap_or_default();
    object_url(base_url, &format!("{hash}.narinfo"), "")
}

/// Upload every object in plan order: NAR bodies first at all times.
async fn upload_objects<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    staging_dir: &std::path::Path,
    objects: &[StagedObject],
) -> Result<usize, PushError> {
    let mut uploaded = 0;
    for object in objects {
        match plan_mechanics(&object.key, object.size_bytes)? {
            UploadMechanics::Single => {
                upload_single(commands, http, tokens, sleep, inputs, staging_dir, object).await?;
            }
            UploadMechanics::Multipart(shape) => {
                upload_multipart(commands, http, tokens, sleep, inputs, staging_dir, object, shape)
                    .await?;
            }
        }
        uploaded += 1;
    }
    Ok(uploaded)
}

/// The single PUT, retried as a unit. The body loads once; each attempt
/// reuses it with a token seconds old.
async fn upload_single<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    staging_dir: &std::path::Path,
    object: &StagedObject,
) -> Result<(), PushError> {
    let body = commands.read_file(&staging_dir.join(&object.file_name)).await?;
    let url = object_url(&inputs.cache_url, &object.key, "");
    let what = format!("PUT {}", object.key);
    with_retries(&what, sleep, || {
        let url = url.clone();
        let body = body.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .put(&url, &token, body, &[])
                .await?;
            require_2xx(&what, answer)
        }
    })
    .await
}

/// The multipart quartet, each piece retried alone; a part that dies
/// aborts the upload best-effort and the failure propagates.
#[allow(clippy::too_many_arguments)]
async fn upload_multipart<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    staging_dir: &std::path::Path,
    object: &StagedObject,
    shape: cachet_core::multipart::PlanShape,
) -> Result<(), PushError> {
    let url = object_url(&inputs.cache_url, &object.key, "?uploads");
    let what = format!("begin {}", object.key);
    let created: cachet_api::UploadCreated =
        with_retries(&what, sleep, || {
            let url = url.clone();
            async move {
                let token = tokens.mint(&inputs.audience).await?;
                let answer = http
                    .post(
                        &url,
                        &token,
                        Vec::new(),
                        &[(
                            "x-cachet-upload-bytes".to_string(),
                            object.size_bytes.to_string(),
                        )],
                    )
                    .await?;
                let answer = require_2xx(&what, answer)?;
                serde_json::from_slice(&answer.body).map_err(|failure| PushError::Detail {
                    message: format!("the begin answer did not parse: {failure}"),
                })
            }
        })
        .await?;

    let mut parts: Vec<cachet_api::UploadedPartBody> = Vec::new();
    for number in 1..=shape.count {
        match upload_one_part(commands, http, tokens, sleep, inputs, staging_dir, object, &created.upload_id, shape, number).await {
            Ok(part) => parts.push(part),
            Err(failure) => {
                abort_multipart(http, tokens, inputs, object, &created.upload_id).await;
                return Err(failure);
            }
        }
    }

    let url = object_url(
        &inputs.cache_url,
        &object.key,
        &format!("?uploadId={}", created.upload_id),
    );
    let body = serde_json::to_vec(&parts).expect("the completion body serializes");
    let what = format!("complete {}", object.key);
    with_retries(&what, sleep, || {
        let url = url.clone();
        let body = body.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http
                .post(
                    &url,
                    &token,
                    body,
                    &[("content-type".to_string(), "application/json".to_string())],
                )
                .await?;
            require_2xx(&what, answer)
        }
    })
    .await?;
    Ok(())
}

/// One part: a ranged read from the staged file and one PUT.
#[allow(clippy::too_many_arguments)]
async fn upload_one_part<C: Commands, H: Http, T: TokenSource>(
    commands: &C,
    http: &H,
    tokens: &T,
    sleep: &Sleeper,
    inputs: &PushInputs,
    staging_dir: &std::path::Path,
    object: &StagedObject,
    upload_id: &str,
    shape: cachet_core::multipart::PlanShape,
    number: u64,
) -> Result<cachet_api::UploadedPartBody, PushError> {
    let offset = (number - 1) * cachet_core::constants::UPLOAD_PART_BYTES;
    let length = if number == shape.count {
        shape.last_len
    } else {
        cachet_core::constants::UPLOAD_PART_BYTES
    };
    let body = commands
        .read_range(&staging_dir.join(&object.file_name), offset, length)
        .await?;
    let url = object_url(
        &inputs.cache_url,
        &object.key,
        &format!("?uploadId={upload_id}&partNumber={number}"),
    );
    let what = format!("part {number} of {}", object.key);
    with_retries(&what, sleep, || {
        let url = url.clone();
        let body = body.clone();
        async move {
            let token = tokens.mint(&inputs.audience).await?;
            let answer = http.put(&url, &token, body, &[]).await?;
            let answer = require_2xx(&what, answer)?;
            serde_json::from_slice(&answer.body).map_err(|failure| PushError::Detail {
                message: format!("the part answer did not parse: {failure}"),
            })
        }
    })
    .await
}

/// The abort: best-effort by contract; a mint failure skips silently and
/// the collector reclaims the upload later.
async fn abort_multipart<H: Http, T: TokenSource>(
    http: &H,
    tokens: &T,
    inputs: &PushInputs,
    object: &StagedObject,
    upload_id: &str,
) {
    let Ok(token) = tokens.mint(&inputs.audience).await else {
        return;
    };
    let url = object_url(
        &inputs.cache_url,
        &object.key,
        &format!("?uploadId={upload_id}"),
    );
    let _ = http.delete(&url, &token).await;
}

/// The retry envelope: an operation runs until it works or the envelope
/// closes, naming the label, the count, and the last complaint.
async fn with_retries<T, Fut>(
    what: &str,
    sleep: &Sleeper,
    mut attempt: impl FnMut() -> Fut,
) -> Result<T, PushError>
where
    Fut: std::future::Future<Output = Result<T, PushError>>,
{
    let mut last = String::new();
    for tries in 0..RETRY_MAX {
        match attempt().await {
            Ok(value) => return Ok(value),
            Err(failure) => {
                last = failure.to_string();
                if let Some(delay_ms) = delay_after(tries) {
                    sleep(delay_ms).await;
                }
            }
        }
    }
    Err(PushError::UploadFailed {
        what: what.to_string(),
        attempts: RETRY_MAX,
        last,
    })
}

/// Any 2xx passes as the wire's ok; everything else fails with the body.
fn require_2xx(what: &str, answer: WireAnswer) -> Result<WireAnswer, PushError> {
    if (200..300).contains(&answer.status) {
        return Ok(answer);
    }
    Err(PushError::UploadFailed {
        what: what.to_string(),
        attempts: 1,
        last: format!(
            "{} {}",
            answer.status,
            String::from_utf8_lossy(&answer.body),
        ),
    })
}

