//! cachet-cli is the user-facing client (CLAUDE.md §4): device-flow login
//! against github.com, managed-block edits of nix.conf and netrc, the CI
//! push driver over cachet-push, keypair generation, and the
//! 404-versus-401 doctor probe.

#![forbid(unsafe_code)]

pub mod config;
pub mod doctor;
pub mod keygen;
pub mod login;
pub mod push;
pub mod setup;

/// The one user-facing failure shape: a sentence, no machinery. Every
/// command's failure path renders it with the `cachet:` prefix, matching
/// the log vocabulary the pipeline already speaks.
#[derive(Debug)]
pub struct CliError(pub String);

impl std::fmt::Display for CliError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for CliError {}

/// Build the shared TLS client once per command.
///
/// # Errors
///
/// [`CliError`] when the TLS stack cannot initialize.
pub fn http_client() -> Result<reqwest::Client, CliError> {
    reqwest::Client::builder()
        .user_agent(concat!("cachet/", env!("CARGO_PKG_VERSION")))
        .build()
        .map_err(|failure| CliError(format!("could not build the HTTP client: {failure}")))
}

//! Where the CLI keeps its state: one directory holding one token per
//! deployment and the URL of the deployment last logged into, so later
//! commands can answer "which cache" without a flag.

use std::path::{Path, PathBuf};

use crate::CliError;

/// Resolve the state directory: the explicit override, then XDG, then
/// the home fallback. The override exists so tests and unusual layouts
/// stay first-class.
///
/// # Errors
///
/// [`CliError`] when no home directory is discoverable.
pub fn state_dir(vars: &[(String, String)]) -> Result<PathBuf, CliError> {
    let value = |name: &str| {
        vars.iter()
            .find(|(key, _)| key == name)
            .map(|(_, v)| v.clone())
            .filter(|v| !v.is_empty())
    };
    if let Some(explicit) = value("CACHET_CONFIG_DIR") {
        return Ok(PathBuf::from(explicit));
    }
    if let Some(xdg) = value("XDG_CONFIG_HOME") {
        return Ok(PathBuf::from(xdg).join("cachet"));
    }
    value("HOME")
        .map(|home| PathBuf::from(home).join(".config").join("cachet"))
        .ok_or_else(|| {
            CliError("no home directory: set CACHET_CONFIG_DIR explicitly".to_string())
        })
}

/// The token file for one deployment, keyed by host so several caches
/// can share the directory.
fn token_path(dir: &Path, host: &str) -> PathBuf {
    dir.join("tokens").join(format!("{host}.token"))
}

/// The file remembering which deployment was logged into most recently.
fn default_url_path(dir: &Path) -> PathBuf {
    dir.join("default-url")
}

/// Persist a login: the token at 0600 under its host, and the base URL
/// as the new default. Re-login overwrites both, so rotation is just
/// logging in again.
///
/// # Errors
///
/// [`CliError`] on any write or permission failure.
pub fn store_login(dir: &Path, host: &str, base_url: &str, token: &str) -> Result<(), CliError> {
    let tokens = dir.join("tokens");
    std::fs::create_dir_all(&tokens)
        .map_err(|failure| CliError(format!("could not create {}: {failure}", tokens.display())))?;
    let path = token_path(dir, host);
    std::fs::write(&path, format!("{token}\n"))
        .map_err(|failure| CliError(format!("could not write {}: {failure}", path.display())))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).map_err(
            |failure| CliError(format!("could not chmod {}: {failure}", path.display())),
        )?;
    }
    std::fs::write(default_url_path(dir), format!("{base_url}\n")).map_err(|failure| {
        CliError(format!(
            "could not write {}: {failure}",
            default_url_path(dir).display()
        ))
    })?;
    Ok(())
}

/// The stored token for a deployment, trimmed. Absence is an answer, not
/// a failure: `Ok(None)` means login has not happened here.
///
/// # Errors
///
/// [`CliError`] on a read failure other than absence.
pub fn read_token(dir: &Path, host: &str) -> Result<Option<String>, CliError> {
    match std::fs::read_to_string(token_path(dir, host)) {
        Ok(text) => Ok(text.lines().next().map(str::trim).filter(|t| !t.is_empty()).map(str::to_string)),
        Err(miss) if miss.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(failure) => Err(CliError(format!(
            "could not read {}: {failure}",
            token_path(dir, host).display()
        ))),
    }
}

/// The deployment last logged into, if any.
#[must_use]
pub fn read_default_url(dir: &Path) -> Option<String> {
    std::fs::read_to_string(default_url_path(dir))
        .ok()
        .map(|text| text.trim().to_string())
        .filter(|text| !text.is_empty())
}

/// The host a base URL names, for netrc and token filenames. A URL
/// whose host cannot be told from its path is a configuration bug, so
/// this fails loudly rather than guessing.
///
/// # Errors
///
/// [`CliError`] on a shape that names no host.
pub fn host_of(base_url: &str) -> Result<String, CliError> {
    let stripped = base_url
        .trim_end_matches('/')
        .strip_prefix("https://")
        .or_else(|| base_url.trim_end_matches('/').strip_prefix("http://"))
        .ok_or_else(|| {
            CliError(format!("the cache URL {base_url:?} must start with https://"))
        })?;
    let host = stripped
        .split(['/', ':', '?', '#'])
        .next()
        .filter(|h| !h.is_empty())
        .ok_or_else(|| CliError(format!("the cache URL {base_url:?} names no host")))?;
    if !host
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '.' || ch == '-')
    {
        return Err(CliError(format!(
            "{host:?} is not a plausible hostname"
        )));
    }
    Ok(host.to_string())
}

/// Resolve which deployment a command talks to: the flag wins, then the
/// stored default.
///
/// # Errors
///
/// [`CliError`] naming the fix when neither exists.
pub fn resolve_cache_url(flag: Option<&str>, dir: &Path) -> Result<String, CliError> {
    if let Some(url) = flag {
        return Ok(url.trim_end_matches('/').to_string());
    }
    read_default_url(dir).ok_or_else(|| {
        CliError("no cache URL: pass --cache-url or run `cachet login --cache-url ...`".to_string())
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_host_grammar_matches_netrc_needs() {
        assert_eq!(host_of("https://cache.example.com").expect("host"), "cache.example.com");
        assert_eq!(
            host_of("https://cache.example.com/").expect("host"),
            "cache.example.com"
        );
        assert_eq!(host_of("https://cache.example.com:8443").expect("host"), "cache.example.com");
        assert!(host_of("cache.example.com").is_err(), "scheme required");
        assert!(host_of("https://").is_err());
        assert!(host_of("https://evil host/").is_err());
    }

    #[test]
    fn store_and_read_round_trip() {
        let dir = tempfile::tempdir().expect("dir");
        store_login(dir.path(), "cache.example.com", "https://cache.example.com", "gho_secret")
            .expect("store");
        assert_eq!(
            read_token(dir.path(), "cache.example.com").expect("read"),
            Some("gho_secret".to_string())
        );
        assert_eq!(
            read_default_url(dir.path()),
            Some("https://cache.example.com".to_string())
        );
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            let mode = std::fs::metadata(token_path(dir.path(), "cache.example.com"))
                .expect("meta")
                .permissions()
                .mode();
            assert_eq!(mode & 0o777, 0o600, "tokens are owner-only");
        }
    }

    #[test]
    fn absence_is_an_answer() {
        let dir = tempfile::tempdir().expect("dir");
        assert_eq!(read_token(dir.path(), "no.such.host").expect("read"), None);
        assert_eq!(read_default_url(dir.path()), None);
    }
}

//! GitHub device-flow login, the laptop's path to a read credential. The
//! deployment's public config names the OAuth App; GitHub answers the
//! flow directly, the worker is never in the loop, and the token lands
//! under the CLI's state directory at 0600.

use crate::CliError;

/// github.com's web half: device code and token polls.
pub const GITHUB_WEB_BASE: &str = "https://github.com";
/// The API half: identity checks.
pub const GITHUB_API_BASE: &str = "https://api.github.com";

/// The scope laptop reads need: org membership is the worker's whole
/// admission test.
const DEVICE_SCOPE: &str = "read:org";

/// One sleep, injected so tests never wait. Milliseconds.
pub type Sleeper = dyn Fn(u64) -> futures_util_sleep::BoxFut + Send + Sync;

mod futures_util_sleep {
    pub type BoxFut = std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send>>;
}

/// What a poll of the token endpoint answered.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PollAnswer {
    /// The user has not entered the code yet.
    Pending,
    /// The server asked for a longer interval.
    SlowDown,
    /// The flow completed.
    Granted {
        /// The OAuth user token.
        token: String,
        /// The scopes GitHub actually granted, for the summary line.
        scope: String,
    },
    /// The device code lapsed before the user finished.
    Expired,
    /// The user declined.
    Denied {
        /// GitHub's own reason text.
        description: String,
    },
}

/// The session the device-code endpoint hands back.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeviceSession {
    /// The code polls are keyed by.
    pub device_code: String,
    /// The code the human types.
    pub user_code: String,
    /// The page the human opens.
    pub verification_uri: String,
    /// How long the session lives, seconds.
    pub expires_in_secs: u64,
    /// The starting poll interval, seconds.
    pub interval_secs: u64,
}

/// The two endpoints a flow needs, plus the identity check that makes
/// the success line honest. Scripted in tests, reqwest in production.
pub trait DeviceServer: Send + Sync {
    /// Ask for a device session.
    fn start(
        &self,
        client_id: &str,
        scope: &str,
    ) -> impl std::future::Future<Output = Result<DeviceSession, CliError>> + Send;

    /// One poll of the token endpoint.
    fn poll(
        &self,
        client_id: &str,
        device_code: &str,
    ) -> impl std::future::Future<Output = Result<PollAnswer, CliError>> + Send;

    /// The login the token authenticates as.
    fn whoami(
        &self,
        token: &str,
    ) -> impl std::future::Future<Output = Result<String, CliError>> + Send;
}

/// Fetch the deployment's public config: the OAuth App's client id, the
/// orgs, the host name, and the key laptops learn to trust.
///
/// # Errors
///
/// [`CliError`] when the URL answers badly or the body is not the
/// document.
pub async fn fetch_public_config(
    client: &reqwest::Client,
    cache_url: &str,
) -> Result<cachet_api::PublicConfig, CliError> {
    let url = format!("{cache_url}/api/public/config");
    let answer = client
        .get(&url)
        .send()
        .await
        .map_err(|failure| CliError(format!("{url} did not answer: {failure}")))?;
    if !answer.status().is_success() {
        return Err(CliError(format!(
            "{url} answered {}: this cache is not serving its public config",
            answer.status().as_u16()
        )));
    }
    answer
        .json::<cachet_api::PublicConfig>()
        .await
        .map_err(|failure| CliError(format!("{url} did not return a public config: {failure}")))
}

/// Drive one flow: emit the instructions, poll until an outcome, and
/// identify the human at the end. Answers the token and the login it
/// authenticates as.
///
/// # Errors
///
/// [`CliError`] on denial, expiry, transport failures, or a server that
/// stops making sense.
pub async fn run_device_flow<D: DeviceServer>(
    server: &D,
    client_id: &str,
    sleep_ms: &Sleeper,
    tell: &mut dyn FnMut(&str),
) -> Result<(String, String), CliError> {
    let session = server.start(client_id, DEVICE_SCOPE).await?;
    tell(&format!(
        "cachet: open {} and enter {}",
        session.verification_uri, session.user_code
    ));
    let mut interval_ms = session.interval_secs.max(1) * 1000;
    let mut waited_ms = 0_u64;
    let budget_ms = session.expires_in_secs.max(1) * 1000;
    let token = loop {
        sleep_ms(interval_ms).await;
        waited_ms += interval_ms;
        if waited_ms > budget_ms {
            return Err(CliError(
                "the device code expired before the flow finished; run `cachet login` again"
                    .to_string(),
            ));
        }
        match server.poll(client_id, &session.device_code).await? {
            PollAnswer::Pending => {}
            PollAnswer::SlowDown => interval_ms += 5000,
            PollAnswer::Granted { token, .. } => break token,
            PollAnswer::Expired => {
                return Err(CliError(
                    "the device code expired; run `cachet login` again".to_string(),
                ));
            }
            PollAnswer::Denied { description } => {
                return Err(CliError(format!(
                    "the flow was declined{}",
                    if description.is_empty() {
                        String::new()
                    } else {
                        format!(": {description}")
                    }
                )));
            }
        }
    };
    let login = server.whoami(&token).await?;
    Ok((token, login))
}

/// The reqwest-backed server, pointed at the real GitHub hosts.
pub struct GithubLive<'a> {
    client: &'a reqwest::Client,
    web_base: &'a str,
    api_base: &'a str,
}

impl<'a> GithubLive<'a> {
    /// Borrow the client against the default GitHub hosts.
    #[must_use]
    pub fn new(client: &'a reqwest::Client) -> Self {
        Self {
            client,
            web_base: GITHUB_WEB_BASE,
            api_base: GITHUB_API_BASE,
        }
    }
}

#[derive(Debug, serde::Deserialize)]
struct DeviceCodeAnswer {
    device_code: Option<String>,
    user_code: Option<String>,
    verification_uri: Option<String>,
    expires_in: Option<u64>,
    interval: Option<u64>,
    error: Option<String>,
    error_description: Option<String>,
}

#[derive(Debug, serde::Deserialize)]
struct TokenAnswer {
    access_token: Option<String>,
    scope: Option<String>,
    error: Option<String>,
    error_description: Option<String>,
}

#[derive(Debug, serde::Deserialize)]
struct UserAnswer {
    login: Option<String>,
}

fn describe(error: Option<String>, description: Option<String>) -> String {
    match (error, description) {
        (Some(code), Some(text)) => format!("{code}: {text}"),
        (Some(code), None) => code,
        (None, Some(text)) => text,
        (None, None) => "an answer with no fields".to_string(),
    }
}

impl DeviceServer for GithubLive<'_> {
    async fn start(&self, client_id: &str, scope: &str) -> Result<DeviceSession, CliError> {
        let url = format!("{}/login/device/code", self.web_base);
        let answer = self
            .client
            .post(&url)
            .header("accept", "application/json")
            .form(&[("client_id", client_id), ("scope", scope)])
            .send()
            .await
            .map_err(|failure| CliError(format!("{url} did not answer: {failure}")))?;
        let parsed: DeviceCodeAnswer = answer.json().await.map_err(|failure| {
            CliError(format!("{url} did not return a device session: {failure}"))
        })?;
        match parsed {
            DeviceCodeAnswer {
                device_code: Some(device_code),
                user_code: Some(user_code),
                verification_uri: Some(verification_uri),
                expires_in,
                interval,
                ..
            } => Ok(DeviceSession {
                device_code,
                user_code,
                verification_uri,
                expires_in_secs: expires_in.unwrap_or(900),
                interval_secs: interval.unwrap_or(5),
            }),
            other => Err(CliError(format!(
                "{url} refused the device flow: {}",
                describe(other.error, other.error_description)
            ))),
        }
    }

    async fn poll(&self, client_id: &str, device_code: &str) -> Result<PollAnswer, CliError> {
        let url = format!("{}/login/oauth/access_token", self.web_base);
        let answer = self
            .client
            .post(&url)
            .header("accept", "application/json")
            .form(&[
                ("client_id", client_id),
                ("device_code", device_code),
                ("grant_type", "urn:ietf:params:oauth:grant-type:device_code"),
            ])
            .send()
            .await
            .map_err(|failure| CliError(format!("{url} did not answer: {failure}")))?;
        let parsed: TokenAnswer = answer.json().await.map_err(|failure| {
            CliError(format!("{url} did not return a token answer: {failure}"))
        })?;
        if let Some(token) = parsed.access_token.filter(|t| !t.is_empty()) {
            return Ok(PollAnswer::Granted {
                token,
                scope: parsed.scope.unwrap_or_default(),
            });
        }
        Ok(match parsed.error.as_deref().unwrap_or("") {
            "authorization_pending" => PollAnswer::Pending,
            "slow_down" => PollAnswer::SlowDown,
            "expired_token" => PollAnswer::Expired,
            other => PollAnswer::Denied {
                description: if other.is_empty() {
                    describe(None, parsed.error_description)
                } else {
                    describe(Some(other.to_string()), parsed.error_description)
                },
            },
        })
    }

    async fn whoami(&self, token: &str) -> Result<String, CliError> {
        let url = format!("{}/user", self.api_base);
        let answer = self
            .client
            .get(&url)
            .bearer_auth(token)
            .send()
            .await
            .map_err(|failure| CliError(format!("{url} did not answer: {failure}")))?;
        if !answer.status().is_success() {
            return Err(CliError(format!(
                "the new token could not answer {url} ({}): the flow granted nothing usable",
                answer.status().as_u16()
            )));
        }
        let parsed: UserAnswer = answer
            .json()
            .await
            .map_err(|failure| CliError(format!("{url} did not return a user: {failure}")))?;
        parsed.login.filter(|l| !l.is_empty()).ok_or_else(|| {
            CliError(format!("{url} answered without a login field"))
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;

    /// A scripted server: sessions on demand, poll answers in order.
    struct FakeServer {
        session: DeviceSession,
        polls: Mutex<std::collections::VecDeque<Result<PollAnswer, CliError>>>,
        login: String,
    }

    impl DeviceServer for FakeServer {
        async fn start(&self, client_id: &str, scope: &str) -> Result<DeviceSession, CliError> {
            assert_eq!(client_id, "the-client-id");
            assert_eq!(scope, DEVICE_SCOPE);
            Ok(self.session.clone())
        }
        async fn poll(&self, _client_id: &str, _device_code: &str) -> Result<PollAnswer, CliError> {
            self.polls
                .lock()
                .expect("polls")
                .pop_front()
                .expect("a scripted poll")
        }
        async fn whoami(&self, _token: &str) -> Result<String, CliError> {
            Ok(self.login.clone())
        }
    }

    fn server(polls: Vec<PollAnswer>) -> FakeServer {
        FakeServer {
            session: DeviceSession {
                device_code: "dev".to_string(),
                user_code: "CAFE-1234".to_string(),
                verification_uri: "https://github.com/login/device".to_string(),
                expires_in_secs: 900,
                interval_secs: 1,
            },
            polls: Mutex::new(polls.into_iter().map(Ok).collect()),
            login: "a-user".to_string(),
        }
    }

    fn no_sleep() -> Box<Sleeper> {
        Box::new(|_ms| Box::pin(async {}))
    }

    #[tokio::test]
    async fn pending_then_granted_prints_the_instructions() {
        let server = server(vec![
            PollAnswer::Pending,
            PollAnswer::Granted {
                token: "gho_tok".to_string(),
                scope: "read:org".to_string(),
            },
        ]);
        let sleep = no_sleep();
        let mut lines = Vec::new();
        let (token, login) = run_device_flow(&server, "the-client-id", &sleep, &mut |line| {
            lines.push(line.to_string());
        })
        .await
        .expect("flow");
        assert_eq!(token, "gho_tok");
        assert_eq!(login, "a-user");
        assert_eq!(
            lines,
            vec!["cachet: open https://github.com/login/device and enter CAFE-1234".to_string()]
        );
    }

    #[tokio::test]
    async fn slow_down_lengthens_and_denial_names_the_reason() {
        let server = server(vec![
            PollAnswer::SlowDown,
            PollAnswer::Granted {
                token: "gho_tok".to_string(),
                scope: String::new(),
            },
        ]);
        let sleep = no_sleep();
        let (token, _) = run_device_flow(&server, "the-client-id", &sleep, &mut |_| {})
            .await
            .expect("flow");
        assert_eq!(token, "gho_tok");

        let server = server(vec![PollAnswer::Denied {
            description: "access_denied".to_string(),
        }]);
        let sleep = no_sleep();
        let failure = run_device_flow(&server, "the-client-id", &sleep, &mut |_| {})
            .await
            .expect_err("denied");
        assert!(failure.0.contains("access_denied"), "{failure}");
    }

    #[tokio::test]
    async fn the_budget_closes_on_expiry() {
        let server = FakeServer {
            session: DeviceSession {
                device_code: "dev".to_string(),
                user_code: "CAFE-1234".to_string(),
                verification_uri: "u".to_string(),
                expires_in_secs: 2,
                interval_secs: 1,
            },
            polls: Mutex::new(
                [PollAnswer::Pending, PollAnswer::Pending, PollAnswer::Pending]
                    .into_iter()
                    .map(Ok)
                    .collect(),
            ),
            login: "a-user".to_string(),
        };
        let sleep = no_sleep();
        let failure = run_device_flow(&server, "the-client-id", &sleep, &mut |_| {})
            .await
            .expect_err("expired");
        assert!(failure.0.contains("expired"), "{failure}");
    }
}

