//! The CI driver: turns the job environment into pipeline inputs and
//! renders the pipeline's events as the `cachet:` log vocabulary. The
//! composite action exports the CACHET_* variables; this module resolves,
//! never the other way around, so running the binary standalone answers
//! the same missing-input diagnosis the action would.
//!
//! The contract on failure is the previous post step's: log and exit
//! zero. A broken push must never break the build it rides on.

use cachet_push::pipeline::PushEvent;

use crate::CliError;

/// Every variable the post phase reads, resolved.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PushEnv {
    /// Where the cache lives.
    pub cache_url: String,
    /// The OIDC audience.
    pub audience: String,
    /// The lease project (`owner-repo`).
    pub project: String,
    /// Whitespace-split flake installables.
    pub installables: Vec<String>,
    /// The upstream filter target.
    pub upstream_url: String,
    /// GITHUB_REF == CACHET_DEFAULT_BRANCH_REF, both nonempty.
    pub is_default_branch: bool,
    /// RUNNER_TEMP, where the snapshot between main and post lives.
    pub runner_temp: std::path::PathBuf,
}

/// What resolving the environment concluded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EnvResolution {
    /// `CACHET_PUSH=false`: the job read-only.
    Disabled,
    /// Everything needed is present.
    Ready(PushEnv),
    /// These variables are unset or empty.
    Missing(Vec<String>),
}

/// The default upstream filter, when the job does not say.
const UPSTREAM_DEFAULT: &str = "https://cache.nixos.org";
/// The default renewal ref, when the job does not say.
const DEFAULT_BRANCH_REF: &str = "refs/heads/main";

/// Resolve the job environment. Resolution is data-in, answers-out: the
/// caller collects `std::env::vars` once.
#[must_use]
pub fn resolve_env(vars: &[(String, String)]) -> EnvResolution {
    let value = |name: &str| {
        vars.iter()
            .find(|(key, _)| key == name)
            .map(|(_, v)| v.trim().to_string())
            .filter(|v| !v.is_empty())
    };
    if value("CACHET_PUSH").as_deref() == Some("false") {
        return EnvResolution::Disabled;
    }
    let cache_url = value("CACHET_CACHE_URL");
    let audience = value("CACHET_AUDIENCE");
    let project = value("CACHET_PROJECT");
    let missing: Vec<String> = [
        ("CACHET_CACHE_URL", cache_url.is_none()),
        ("CACHET_AUDIENCE", audience.is_none()),
        ("CACHET_PROJECT", project.is_none()),
    ]
    .into_iter()
    .filter(|(_, absent)| *absent)
    .map(|(name, _)| name.to_string())
    .collect();
    let (Some(cache_url), Some(audience), Some(project)) = (cache_url, audience, project)
    else {
        return EnvResolution::Missing(missing);
    };
    let upstream_url = value("CACHET_UPSTREAM_URL").unwrap_or_else(|| UPSTREAM_DEFAULT.to_string());
    let default_ref = value("CACHET_DEFAULT_BRANCH_REF").unwrap_or_else(|| DEFAULT_BRANCH_REF.to_string());
    let github_ref = value("GITHUB_REF");
    let is_default_branch = matches!(github_ref, Some(actual) if actual == default_ref);
    let installables = value("CACHET_ROOTS")
        .map(|roots| roots.split_whitespace().map(str::to_string).collect())
        .unwrap_or_default();
    let runner_temp = value("RUNNER_TEMP")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from("/tmp"));
    EnvResolution::Ready(PushEnv {
        cache_url,
        audience,
        project,
        installables,
        upstream_url,
        is_default_branch,
        runner_temp,
    })
}

/// The missing-input diagnosis, verbatim the previous post step's shape:
/// one sentence naming what to set and who normally sets it.
#[must_use]
pub fn missing_message(missing: &[String]) -> String {
    format!(
        "cachet: nothing pushed, because {} {} unset. The cachet setup action exports these to the job environment; if you are running cachet push directly, set them yourself.",
        missing.join(", "),
        if missing.len() == 1 { "is" } else { "are" },
    )
}

/// The `cachet:` vocabulary: one line per event, matching the previous
/// post step's wording so existing log scanners keep working.
#[must_use]
pub fn render_event(event: &PushEvent) -> String {
    match event {
        PushEvent::SnapshotTaken => "cachet: store snapshot taken".to_string(),
        PushEvent::MainSnapshotFailed { message } => {
            format!("cachet: could not snapshot the store, so nothing will be pushed. {message}")
        }
        PushEvent::NothingAdded => "cachet: the job added nothing to the store".to_string(),
        PushEvent::InstallableUnresolved { installable } => {
            format!("cachet: could not resolve {installable}; it will not be a lease root")
        }
        PushEvent::UpstreamTally {
            to_push,
            upstream_hits,
            probe_failures,
        } => tally_line(
            &format!("{to_push} not upstream, {upstream_hits} already upstream"),
            *probe_failures,
        ),
        PushEvent::CacheTally {
            to_upload,
            cache_hits,
            probe_failures,
        } => tally_line(
            &format!("{to_upload} new to cachet, {cache_hits} already cached"),
            *probe_failures,
        ),
        PushEvent::UploadedObjects { count } => format!("cachet: uploaded {count} objects"),
        PushEvent::LeaseSkippedNotDefaultBranch => {
            "cachet: not the default branch, so the lease is not renewed".to_string()
        }
        PushEvent::LeaseRenewed { project } => format!("cachet: lease renewed for {project}"),
    }
}

fn tally_line(base: &str, probe_failures: usize) -> String {
    if probe_failures == 0 {
        format!("cachet: {base}")
    } else {
        format!("cachet: {base}, {probe_failures} probes failed (kept)")
    }
}

/// The main step: snapshot the store to the hand-off file. Failures are
/// reported and swallowed; the post step treats a missing file as an
/// empty before-set.
pub async fn run_snapshot(
    vars: &[(String, String)],
    commands: &cachet_push::real::TokioCommands,
    tell: &mut dyn FnMut(&str),
) {
    let runner_temp = vars
        .iter()
        .find(|(key, _)| key == "RUNNER_TEMP")
        .map(|(_, v)| std::path::PathBuf::from(v))
        .unwrap_or_else(|| std::path::PathBuf::from("/tmp"));
    let path = cachet_push::adapters::snapshot_path(&runner_temp);
    let mut sink = |event: PushEvent| tell(&render_event(&event));
    if let Some(text) = cachet_push::pipeline::main_snapshot(commands, &mut sink)
        .await
        .unwrap_or(None)
    {
        if let Err(failure) = std::fs::write(&path, text) {
            tell(&format!(
                "cachet: could not write the snapshot file {}: {failure}, so nothing will be pushed",
                path.display()
            ));
        }
    }
}

/// The post step: the whole pipeline, never failing the job.
pub async fn run_push(vars: &[(String, String)], tell: &mut dyn FnMut(&str)) {
    match resolve_env(vars) {
        EnvResolution::Disabled => {
            tell("cachet: pushing is disabled for this job");
        }
        EnvResolution::Missing(missing) => {
            tell(&missing_message(&missing));
        }
        EnvResolution::Ready(env) => run_pipeline(env, vars, tell).await,
    }
}

/// Wire the real adapters and drive. Every failure ends as one
/// `cachet:` line; the exit code stays zero by the caller's contract.
async fn run_pipeline(env: PushEnv, vars: &[(String, String)], tell: &mut dyn FnMut(&str)) {
    if let Err(failure) = run_pipeline_inner(env, vars, tell).await {
        tell(&format!("cachet: {failure}"));
    }
}

async fn run_pipeline_inner(
    env: PushEnv,
    vars: &[(String, String)],
    tell: &mut dyn FnMut(&str),
) -> Result<(), CliError> {
    let oidc_env = cachet_push::oidc::oidc_env(vars).map_err(|failure| CliError(failure.to_string()))?;
    let http =
        cachet_push::real::ReqwestHttp::new().map_err(|failure| CliError(failure.to_string()))?;
    let commands = cachet_push::real::TokioCommands;
    let tokens = cachet_push::oidc::OidcTokens::new(&oidc_env, &http);
    let sleep = |ms: u64| -> std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send>> {
        Box::pin(tokio::time::sleep(std::time::Duration::from_millis(ms)))
    };
    let adapters = cachet_push::adapters::Adapters {
        commands: &commands,
        http: &http,
        tokens: &tokens,
        sleep: &sleep,
    };
    let before = std::fs::read_to_string(cachet_push::adapters::snapshot_path(&env.runner_temp))
        .unwrap_or_default();
    // why: the staging tree exists only for the `nix copy` half of this
    // run; it dies with the guard.
    let staging = tempfile::tempdir()
        .map_err(|failure| CliError(format!("could not make the staging directory: {failure}")))?;
    let inputs = cachet_push::pipeline::PushInputs {
        cache_url: env.cache_url,
        audience: env.audience,
        project: env.project,
        installables: env.installables,
        upstream_url: env.upstream_url,
        is_default_branch: env.is_default_branch,
    };
    let mut sink = |event: PushEvent| tell(&render_event(&event));
    cachet_push::pipeline::push(
        &adapters,
        &inputs,
        &before,
        staging.path(),
        &mut sink,
    )
    .await
    .map_err(|failure| CliError(failure.to_string()))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vars(pairs: &[(&str, &str)]) -> Vec<(String, String)> {
        pairs
            .iter()
            .map(|(k, v)| ((*k).to_string(), (*v).to_string()))
            .collect()
    }

    #[test]
    fn resolution_reports_exactly_what_is_missing() {
        let resolved = resolve_env(&vars(&[("CACHET_CACHE_URL", "https://cache.example.com")]));
        match resolved {
            EnvResolution::Missing(missing) => {
                assert_eq!(missing, vec!["CACHET_AUDIENCE", "CACHET_PROJECT"]);
            }
            other => panic!("expected Missing, got {other:?}"),
        }
        assert_eq!(
            missing_message(&["CACHET_PROJECT".to_string()]),
            "cachet: nothing pushed, because CACHET_PROJECT is unset. The cachet setup action exports these to the job environment; if you are running cachet push directly, set them yourself."
        );
    }

    #[test]
    fn resolution_defaults_and_branch_gate() {
        let resolved = resolve_env(&vars(&[
            ("CACHET_CACHE_URL", "https://cache.example.com"),
            ("CACHET_AUDIENCE", "cachet"),
            ("CACHET_PROJECT", "org-repo"),
            ("CACHET_ROOTS", ".#a  .#b\n.#c"),
            ("GITHUB_REF", "refs/heads/main"),
        ]));
        match resolved {
            EnvResolution::Ready(env) => {
                assert_eq!(env.upstream_url, UPSTREAM_DEFAULT);
                assert!(env.is_default_branch, "main matches the default ref");
                assert_eq!(env.installables, vec![".#a", ".#b", ".#c"]);
            }
            other => panic!("expected Ready, got {other:?}"),
        }
        let off = resolve_env(&vars(&[
            ("CACHET_CACHE_URL", "https://cache.example.com"),
            ("CACHET_AUDIENCE", "cachet"),
            ("CACHET_PROJECT", "org-repo"),
            ("GITHUB_REF", "refs/pull/7/merge"),
        ]));
        match off {
            EnvResolution::Ready(env) => assert!(!env.is_default_branch),
            other => panic!("expected Ready, got {other:?}"),
        }
        // An empty GITHUB_REF never matches: undefined answers keep out.
        let blank = resolve_env(&vars(&[
            ("CACHET_CACHE_URL", "https://cache.example.com"),
            ("CACHET_AUDIENCE", "cachet"),
            ("CACHET_PROJECT", "org-repo"),
        ]));
        match blank {
            EnvResolution::Ready(env) => assert!(!env.is_default_branch),
            other => panic!("expected Ready, got {other:?}"),
        }
    }

    #[test]
    fn disabled_wins_over_readiness() {
        let resolved = resolve_env(&vars(&[("CACHET_PUSH", "false")]));
        assert_eq!(resolved, EnvResolution::Disabled);
    }

    #[test]
    fn the_vocabulary_holds() {
        assert_eq!(
            render_event(&PushEvent::SnapshotTaken),
            "cachet: store snapshot taken"
        );
        assert_eq!(
            render_event(&PushEvent::NothingAdded),
            "cachet: the job added nothing to the store"
        );
        assert_eq!(
            render_event(&PushEvent::UpstreamTally {
                to_push: 4,
                upstream_hits: 9,
                probe_failures: 0,
            }),
            "cachet: 4 not upstream, 9 already upstream"
        );
        assert_eq!(
            render_event(&PushEvent::CacheTally {
                to_upload: 3,
                cache_hits: 1,
                probe_failures: 2,
            }),
            "cachet: 3 new to cachet, 1 already cached, 2 probes failed (kept)"
        );
        assert_eq!(
            render_event(&PushEvent::UploadedObjects { count: 7 }),
            "cachet: uploaded 7 objects"
        );
        assert_eq!(
            render_event(&PushEvent::LeaseSkippedNotDefaultBranch),
            "cachet: not the default branch, so the lease is not renewed"
        );
        assert_eq!(
            render_event(&PushEvent::LeaseRenewed {
                project: "org-repo".to_string()
            }),
            "cachet: lease renewed for org-repo"
        );
        assert_eq!(
            render_event(&PushEvent::InstallableUnresolved {
                installable: ".#gone".to_string()
            }),
            "cachet: could not resolve .#gone; it will not be a lease root"
        );
    }
}

//! The doctor probe: answers "is this machine wired to read" the way an
//! operator does, but mechanically. The load-bearing distinction is
//! 404-versus-401: the worker authenticates before it consults the
//! bucket, so a 404 proves the credential works (the probed hash is
//! simply absent) and a 401 proves it does not.

use crate::CliError;

/// One check's outcome. `ok` answers the summary; `detail` explains the
/// failure to the human reading it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Probe {
    /// What was checked, one short clause.
    pub name: String,
    /// Whether it held.
    pub ok: bool,
    /// What the check answer meant, or what to do about it.
    pub detail: String,
}

impl Probe {
    fn pass(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: true,
            detail,
        }
    }

    fn fail(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: false,
            detail,
        }
    }
}

/// A hash that parses but cannot exist: all zero bits but the last.
const PROBE_NARINFO: &str = "0000000000000000000000000000000a.narinfo";

/// Run every probe against one deployment: the unauthenticated health
/// document, the public config, the refusal of an anonymous read, and —
/// when a token is stored — the authenticated read and GitHub identity.
/// `token` is what the state directory held for this host (absence is
/// itself a probe outcome, not an error).
pub async fn run_doctor(
    client: &reqwest::Client,
    cache_url: &str,
    token: Option<&str>,
    api_base: &str,
) -> Vec<Probe> {
    let mut probes = Vec::new();

    match client
        .get(format!("{cache_url}/nix-cache-info"))
        .send()
        .await
    {
        Ok(answer) if answer.status().is_success() => {
            let body = answer.text().await.unwrap_or_default();
            if body.contains("StoreDir: /nix/store") {
                probes.push(Probe::pass(
                    "the cache answers /nix-cache-info",
                    format!("{cache_url} is serving"),
                ));
            } else {
                probes.push(Probe::fail(
                    "the cache answers /nix-cache-info",
                    "the body names no store dir: is this a cachet deployment?".to_string(),
                ));
            }
        }
        Ok(answer) => probes.push(Probe::fail(
            "the cache answers /nix-cache-info",
            format!("answered {}", answer.status().as_u16()),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the cache answers /nix-cache-info",
            format!("no answer: {failure}"),
        )),
    }

    let config = match crate::login::fetch_public_config(client, cache_url).await {
        Ok(config) => {
            probes.push(Probe::pass(
                "the public config serves",
                format!(
                    "host {}, orgs [{}], key {}",
                    config.host,
                    config.orgs.join(", "),
                    config.public_key.split(':').next().unwrap_or("?")
                ),
            ));
            Some(config)
        }
        Err(failure) => {
            probes.push(Probe::fail("the public config serves", failure.to_string()));
            None
        }
    };

    let probe_url = format!("{cache_url}/{PROBE_NARINFO}");
    match client.get(&probe_url).send().await {
        Ok(answer) if answer.status().as_u16() == 401 => probes.push(Probe::pass(
            "anonymous reads refuse",
            "401 before the bucket, as the auth order requires".to_string(),
        )),
        Ok(answer) => probes.push(Probe::fail(
            "anonymous reads refuse",
            format!(
                "answered {} instead of 401: the read guard is misconfigured",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "anonymous reads refuse",
            format!("no answer: {failure}"),
        )),
    }

    let Some(token) = token else {
        probes.push(Probe::fail(
            "a stored login exists",
            format!("no token for this host: run `cachet login --cache-url {cache_url}`"),
        ));
        return probes;
    };
    probes.push(Probe::pass(
        "a stored login exists",
        "the state directory holds a token".to_string(),
    ));

    match client.get(&probe_url).bearer_auth(token).send().await {
        Ok(answer) if answer.status().as_u16() == 404 => probes.push(Probe::pass(
            "the stored token reads",
            "404 means authenticated-and-absent: the wiring works".to_string(),
        )),
        Ok(answer) if answer.status().is_success() => probes.push(Probe::pass(
            "the stored token reads",
            "the probe path unexpectedly exists, which still proves auth".to_string(),
        )),
        Ok(answer) => probes.push(Probe::fail(
            "the stored token reads",
            format!(
                "answered {}: re-run `cachet login`; if that holds, the token's org membership lapsed",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the stored token reads",
            format!("no answer: {failure}"),
        )),
    }

    match client
        .get(format!("{api_base}/user"))
        .bearer_auth(token)
        .send()
        .await
    {
        Ok(answer) if answer.status().is_success() => {
            #[derive(serde::Deserialize)]
            struct User {
                login: Option<String>,
            }
            match answer.json::<User>().await {
                Ok(User { login: Some(login) }) => probes.push(Probe::pass(
                    "the token identifies",
                    format!("authenticates as {login}"),
                )),
                _ => probes.push(Probe::fail(
                    "the token identifies",
                    "GitHub answered without a login".to_string(),
                )),
            }
        }
        Ok(answer) => probes.push(Probe::fail(
            "the token identifies",
            format!(
                "GitHub answered {}: the token is revoked or expired; run `cachet login` again",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the token identifies",
            format!("no answer: {failure}"),
        )),
    }

    if let Some(config) = config {
        let mut memberships = 0_usize;
        let mut denied_orgs: Vec<String> = Vec::new();
        for org in &config.orgs {
            let url = format!("{api_base}/user/memberships/orgs/{org}");
            match client.get(&url).bearer_auth(token).send().await {
                Ok(answer) if answer.status().is_success() => memberships += 1,
                _ => denied_orgs.push(org.clone()),
            }
        }
        if memberships > 0 {
            probes.push(Probe::pass(
                "org membership holds",
                format!("a member of {memberships} served org(s)"),
            ));
        } else {
            probes.push(Probe::fail(
                "org membership holds",
                format!(
                    "a member of none of [{}]: the worker will refuse every read",
                    denied_orgs.join(", ")
                ),
            ));
        }
    }

    probes
}

/// Render the probe list in the report's shape: an `ok`/`FAIL` line per
/// probe. Answers whether everything held.
#[must_use]
pub fn render(probes: &[Probe]) -> (Vec<String>, bool) {
    let mut all_ok = true;
    let mut lines = Vec::new();
    for probe in probes {
        if probe.ok {
            lines.push(format!("ok   {}: {}", probe.name, probe.detail));
        } else {
            all_ok = false;
            lines.push(format!("FAIL {}: {}", probe.name, probe.detail));
        }
    }
    (lines, all_ok)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_separates_ok_from_fail() {
        let probes = vec![
            Probe::pass("a", "fine".to_string()),
            Probe::fail("b", "broken".to_string()),
        ];
        let (lines, all_ok) = render(&probes);
        assert!(!all_ok);
        assert_eq!(lines[0], "ok   a: fine");
        assert_eq!(lines[1], "FAIL b: broken");
        let (happy, all_ok) = render(&[Probe::pass("a", "fine".to_string())]);
        assert!(all_ok);
        assert_eq!(happy.len(), 1);
    }
}

//! The `cachet` binary: argv in, one command out. All policy lives in
//! the library modules; this file parses, wires the environment, and
//! picks the exit code.

use std::process::ExitCode;

use cachet_cli::config;
use clap::{Parser, Subcommand};

/// The cachet client: log in with GitHub, wire nix to the deployment,
/// push from CI.
#[derive(Parser)]
#[command(name = "cachet", version, about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Log in to a deployment with GitHub's device flow and store the
    /// read token.
    Login {
        /// The cache's base URL (remembered for later commands).
        #[arg(long)]
        cache_url: String,
    },
    /// Write this machine's nix.conf and netrc so builds substitute from
    /// the cache, then restart the daemon. Requires `cachet login` first.
    Setup {
        /// The cache's base URL; defaults to the one logged into.
        #[arg(long)]
        cache_url: Option<String>,
    },
    /// Probe the read wiring against a deployment and report what holds.
    Doctor {
        /// The cache's base URL; defaults to the one logged into.
        #[arg(long)]
        cache_url: Option<String>,
    },
    /// Generate a deployment's ed25519 signing keypair. Bootstrap only.
    Keygen {
        /// The key's name: `<host>-1` of the deployment.
        #[arg(long)]
        name: String,
        /// Write `cachet-key.secret` (0600) and `cachet-key.public` here
        /// instead of printing the secret.
        #[arg(long)]
        out_dir: Option<std::path::PathBuf>,
    },
    /// CI mode: with --snapshot-only the composite's main step (snapshot
    /// the store); without it the post step (push what the job added).
    /// Reads the job's CACHET_* environment and always exits zero.
    Push {
        /// Only snapshot the store for a later post step.
        #[arg(long)]
        snapshot_only: bool,
    },
}

#[tokio::main]
async fn main() -> ExitCode {
    let cli = Cli::parse();
    let vars: Vec<(String, String)> = std::env::vars().collect();
    match cli.command {
        Command::Login { cache_url } => run(&login(vars, cache_url).await),
        Command::Setup { cache_url } => run(&setup(vars, cache_url).await),
        Command::Doctor { cache_url } => doctor(vars, cache_url).await,
        Command::Keygen { name, out_dir } => run(&keygen(&name, out_dir.as_deref())),
        Command::Push { snapshot_only } => {
            if snapshot_only {
                let commands = cachet_push::real::TokioCommands;
                cachet_cli::push::run_snapshot(&vars, &commands, &mut |line| println!("{line}"))
                    .await;
            } else {
                cachet_cli::push::run_push(&vars, &mut |line| println!("{line}")).await;
            }
            // The CI contract: a push failure is a log line, never a red job.
            ExitCode::SUCCESS
        }
    }
}

/// The shared failure-to-exit-code translation for ordinary commands.
fn run(result: &Result<(), cachet_cli::CliError>) -> ExitCode {
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(failure) => {
            eprintln!("cachet: {failure}");
            ExitCode::FAILURE
        }
    }
}

/// The login flow end to end: config from the deployment, flow against
/// GitHub, token into the state directory.
async fn login(vars: Vec<(String, String)>, cache_url: String) -> Result<(), cachet_cli::CliError> {
    let url = cache_url.trim_end_matches('/').to_string();
    let client = cachet_cli::http_client()?;
    let config = cachet_cli::login::fetch_public_config(&client, &url).await?;
    let server = cachet_cli::login::GithubLive::new(&client);
    let sleep = |ms: u64| -> std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send>> {
        Box::pin(tokio::time::sleep(std::time::Duration::from_millis(ms)))
    };
    let (token, who) = cachet_cli::login::run_device_flow(
        &server,
        &config.oauth_client_id,
        &sleep,
        &mut |line| println!("{line}"),
    )
    .await?;
    let dir = config::state_dir(&vars)?;
    config::store_login(&dir, &config.host, &url, &token)?;
    println!("cachet: logged in to {} as {who}", config.host);
    println!("cachet: run `cachet setup` to wire this machine's nix");
    Ok(())
}

/// The setup flow: token from the state directory, config from the
/// deployment, files through the privileged helpers, daemon restarted.
async fn setup(
    vars: Vec<(String, String)>,
    cache_url: Option<String>,
) -> Result<(), cachet_cli::CliError> {
    let dir = config::state_dir(&vars)?;
    let url = config::resolve_cache_url(cache_url.as_deref(), &dir)?;
    let client = cachet_cli::http_client()?;
    let config = cachet_cli::login::fetch_public_config(&client, &url).await?;
    let token = config::read_token(&dir, &config.host)?.ok_or_else(|| {
        cachet_cli::CliError(format!(
            "no stored login for {}: run `cachet login --cache-url {url}` first",
            config.host
        ))
    })?;
    let paths = resolve_setup_paths(&vars);
    let sudo = vars
        .iter()
        .find(|(key, _)| key == "CACHET_SUDO")
        .map(|(_, v)| v.clone())
        .unwrap_or_else(|| "sudo".to_string());
    let run = |argv: &[&str]| -> Result<(), String> {
        let invocation: Vec<String> = if sudo.is_empty() {
            argv.iter().map(ToString::to_string).collect()
        } else {
            std::iter::once(sudo.clone())
                .chain(argv.iter().map(ToString::to_string))
                .collect()
        };
        let outcome = std::process::Command::new(&invocation[0])
            .args(&invocation[1..])
            .status()
            .map_err(|failure| format!("could not run {}: {failure}", invocation[0]))?;
        outcome
            .success()
            .then_some(())
            .ok_or_else(|| format!("{} exited {outcome}", invocation.join(" ")))
    };
    let install = {
        let run = &run;
        move |path: &std::path::Path, contents: &str, mode: u32| -> Result<(), String> {
            // why: write fully, then move into place; a half-written
            // system config is worse than a stale one.
            let tmp = std::env::temp_dir().join(format!(
                "cachet-setup-{}-{}",
                std::process::id(),
                path.file_name().unwrap_or_default().to_string_lossy()
            ));
            std::fs::write(&tmp, contents).map_err(|failure| format!("{tmp:?}: {failure}"))?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                std::fs::set_permissions(&tmp, std::fs::Permissions::from_mode(mode))
                    .map_err(|failure| format!("chmod {tmp:?}: {failure}"))?;
            }
            if let Some(parent) = path.parent() {
                run(&["mkdir", "-p", &parent.to_string_lossy()])?;
            }
            run(&["cp", &tmp.to_string_lossy(), &path.to_string_lossy()])?;
            run(&["chmod", &format!("{mode:o}"), &path.to_string_lossy()])?;
            let _ = std::fs::remove_file(&tmp);
            Ok(())
        }
    };
    let report = cachet_cli::setup::run_setup(
        &paths,
        &cachet_cli::setup::SetupInput {
            cache_url: url,
            public_key: config.public_key,
            token,
        },
        &run,
        &install,
    )?;
    println!("cachet: {} configured in {}", config.host, report.wrote[0].display());
    for path in &report.wrote[1..] {
        println!("cachet: wrote {}", path.display());
    }
    match report.reload {
        cachet_cli::setup::ReloadOutcome::Systemd => {
            println!("cachet: nix-daemon restarted with systemctl, so the new configuration is live");
        }
        cachet_cli::setup::ReloadOutcome::Launchctl(label) => {
            println!("cachet: nix-daemon restarted ({label}), so the new configuration is live");
        }
        cachet_cli::setup::ReloadOutcome::DeterminateInit => {
            println!("cachet: determinate-nixd re-initialized, so the new configuration is live");
        }
        cachet_cli::setup::ReloadOutcome::Failed => {
            eprintln!("cachet: could NOT restart nix-daemon, so the settings above are not in effect yet.");
            eprintln!("  Substitution will keep returning 401 until it reloads. Restart it with:");
            eprintln!("    sudo launchctl kickstart -k system/systems.determinate.nix-daemon   # macOS, Determinate");
            eprintln!("    sudo launchctl kickstart -k system/org.nixos.nix-daemon              # macOS, upstream");
            eprintln!("    sudo systemctl restart nix-daemon                                    # linux");
        }
    }
    Ok(())
}

/// The path defaults and their environment overrides, plus the
/// Determinate detection: the explicit answer wins, then the PATH probe.
fn resolve_setup_paths(vars: &[(String, String)]) -> cachet_cli::setup::SetupPaths {
    let value = |name: &str, default: &str| {
        vars.iter()
            .find(|(key, _)| key == name)
            .map(|(_, v)| v.clone())
            .filter(|v| !v.is_empty())
            .unwrap_or_else(|| default.to_string())
    };
    let determinate = match value("CACHET_DETERMINATE", "").as_str() {
        "1" => true,
        "0" => false,
        _ => on_path("determinate-nixd", &value("PATH", "/usr/bin:/bin")),
    };
    cachet_cli::setup::SetupPaths {
        netrc: value("CACHET_NETRC_PATH", "/etc/nix/netrc").into(),
        nix_custom_conf: value("CACHET_NIX_CUSTOM_CONF_PATH", "/etc/nix/nix.custom.conf").into(),
        determinate_config: value(
            "CACHET_DETERMINATE_CONFIG_PATH",
            "/etc/determinate/config.json",
        )
        .into(),
        launch_daemons: value("CACHET_LAUNCH_DAEMONS_DIR", "/Library/LaunchDaemons").into(),
        determinate,
    }
}

/// Is `verb` runnable from this PATH?
fn on_path(verb: &str, path_var: &str) -> bool {
    path_var
        .split(':')
        .map(std::path::PathBuf::from)
        .any(|dir| dir.join(verb).is_file())
}

/// The probe run, printing every line; the exit code answers the
/// aggregate.
async fn doctor(vars: Vec<(String, String)>, cache_url: Option<String>) -> ExitCode {
    let outcome = async {
        let dir = config::state_dir(&vars)?;
        let url = config::resolve_cache_url(cache_url.as_deref(), &dir)?;
        let host = config::host_of(&url)?;
        let client = cachet_cli::http_client()?;
        let token = config::read_token(&dir, &host)?;
        Ok::<_, cachet_cli::CliError>((url, client, token))
    }
    .await;
    match outcome {
        Ok((url, client, token)) => {
            let probes = cachet_cli::doctor::run_doctor(
                &client,
                &url,
                token.as_deref(),
                cachet_cli::login::GITHUB_API_BASE,
            )
            .await;
            let (lines, all_ok) = cachet_cli::doctor::render(&probes);
            for line in lines {
                println!("{line}");
            }
            if all_ok {
                ExitCode::SUCCESS
            } else {
                ExitCode::FAILURE
            }
        }
        Err(failure) => {
            eprintln!("cachet: {failure}");
            ExitCode::FAILURE
        }
    }
}

/// keygen: print, or write the pair under --out-dir.
fn keygen(name: &str, out_dir: Option<&std::path::Path>) -> Result<(), cachet_cli::CliError> {
    let (secret, public) =
        cachet_cli::keygen::generate(name).map_err(|failure| cachet_cli::CliError(failure.to_string()))?;
    match out_dir {
        Some(dir) => {
            std::fs::create_dir_all(dir).map_err(|failure| {
                cachet_cli::CliError(format!("could not create {}: {failure}", dir.display()))
            })?;
            let secret_path = dir.join("cachet-key.secret");
            let public_path = dir.join("cachet-key.public");
            std::fs::write(&secret_path, format!("{secret}\n")).map_err(|failure| {
                cachet_cli::CliError(format!("could not write {}: {failure}", secret_path.display()))
            })?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                std::fs::set_permissions(&secret_path, std::fs::Permissions::from_mode(0o600))
                    .map_err(|failure| {
                        cachet_cli::CliError(format!(
                            "could not chmod {}: {failure}",
                            secret_path.display()
                        ))
                    })?;
            }
            std::fs::write(&public_path, format!("{public}\n")).map_err(|failure| {
                cachet_cli::CliError(format!("could not write {}: {failure}", public_path.display()))
            })?;
            println!("cachet: secret key written to {} (keep it there or in a secret store)", secret_path.display());
            println!("cachet: public key written to {}", public_path.display());
            println!("cachet: clients trust it as: {public}");
        }
        None => {
            println!("cachet: the secret key (store it as the deployment's signing secret):");
            println!("{secret}");
            println!("cachet: the public key (clients trust it):");
            println!("{public}");
        }
    }
    Ok(())
}

