// alchemy.run.ts
import alchemy from "alchemy";
import { Worker, KVNamespace, R2Bucket } from "alchemy/cloudflare";

const app = await alchemy("my-app");

// Create resources
const cache = await KVNamespace("cache", {
  title: "my-kv-namespace",
});

const bucket = await R2Bucket("my-bucket", {
  name: "my-bucket",
});

// Deploy a Worker with bindings, custom domain, and cron triggers
export const worker = await Worker("api", {
  name: "api-worker",
  entrypoint: "./src/api.ts",
  bindings: {
    CACHE: cache,                  // KVNamespace binding
    BUCKET: bucket,                // R2Bucket binding
    STAGE: "prod",                 // environment variable
    API_KEY: alchemy.secret("secret-key"), // secret
  },
  domains: ["api.example.com"],    // custom domain
  crons: ["*/5 * * * *"],          // cron triggers
  url: true,                       // workers.dev URL
});

await app.finalize();
