 * no env reads. Every caller passes the raw stage string through
 * `parseLynkStage` first.
 *
 * Topology: three environments, named the same way everywhere (GitHub
 * environments, Infisical slugs, worker suffixes, PlanetScale branches):
 * "preview" (one stage per pull request), "staging" (the main branch,
 * auto-deployed), "production" (a gated cut from main). Development is not
 * an environment: "dev" stages are the laptop, fully local, with no branch
 * and no vault.
 */

export type LynkStage =
  | { readonly kind: "production" }
  | { readonly kind: "staging" }
  | { readonly kind: "preview"; readonly number: number }
  | { readonly kind: "dev"; readonly name: string };

const DEV_NAME_RE = /^[a-z0-9](?:[a-z0-9-]{0,30})?$/;

/**
 * Accepted forms:
 * - "production"        production (gated cut from main)
 * - "staging"           staging (the main branch)
 * - "preview-<number>"  PR previews (preview-42)
 * - "dev"               local stage ("dev") — laptop only
 * - "dev-<name>"        personal local stage ("dev-jane") — laptop only
 */
export function parseLynkStage(raw: string): LynkStage {
  const stage = raw.trim().toLowerCase();
  if (stage === "production") return { kind: "production" };
  if (stage === "staging") return { kind: "staging" };
  const previewMatch = /^preview-(\d{1,6})$/.exec(stage);
  if (previewMatch) return { kind: "preview", number: Number(previewMatch[1]) };
  if (stage === "dev") return { kind: "dev", name: "local" };
  const devMatch = /^dev-([a-z0-9-]+)$/.exec(stage);
  if (devMatch?.[1] && DEV_NAME_RE.test(devMatch[1])) {
    return { kind: "dev", name: devMatch[1] };
  }
  throw new StageParseError(raw);
}

export class StageParseError extends Error {
  constructor(raw: string) {
    super(
      `Invalid stage "${raw}". Expected one of: production, staging, preview-<number>, dev, dev-<name>.`,
    );
    this.name = "StageParseError";
  }
}

/** Deterministic per-stage suffix for worker and resource names. */
export function stageSuffix(stage: LynkStage): string {
  switch (stage.kind) {
    case "production":
      return "";
    case "staging":
      return "-staging";
    case "preview":
      return `-preview-${stage.number}`;
    case "dev":
      return `-dev-${stage.name}`;
  }
}

/** "data-plane" at production -> "lynk-data-plane". At staging ->
 *  "lynk-data-plane-staging". */
export function resolveWorkerName(base: string, stage: LynkStage): string {
  if (!/^[a-z][a-z0-9-]{0,40}$/.test(base)) {
    throw new Error(`Invalid worker base name: "${base}"`);
  }
  return `lynk-${base}${stageSuffix(stage)}`;
}

export type LynkDomains = {
  readonly api?: string;
  readonly app?: string;
};

